package com.questcape;

import com.google.gson.Gson;
import com.google.inject.Provides;
import com.questcape.guide.model.GuideRow;
import com.questcape.guide.repository.GuideRepository;
import com.questcape.integration.QuestCapeSession;
import com.questcape.integration.http.BoundedHttp;
import com.questcape.integration.links.BrowserLinks;
import com.questcape.integration.links.TrainingGuideResolver;
import com.questcape.persistence.JsonStore;
import com.questcape.progress.capture.LiveProgressReader;
import com.questcape.progress.tracking.ProgressService;
import com.questcape.ui.GuideActions;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.plugins.*;
import net.runelite.client.ui.*;

@PluginDescriptor(name = "QuestCape", internalName = "questcape", legacyDataDirectory = "questcape", description = "The ordered OSRS Wiki route with local character progress", tags =
{ "quest", "questcape", "guide", "wiki" })
public class QuestCapePlugin extends Plugin implements GuideActions
{
	@Provides
	@Singleton
	JsonStore provideJsonStore(Gson gson)
	{
		return new JsonStore(gson, this::getPluginDirectory);
	}

	@Inject
	private ClientThread clientThread;
	@Inject
	private Client client;
	@Inject
	private ClientToolbar toolbar;
	@Inject
	private GuideRepository guide;
	@Inject
	private ProgressService progress;
	@Inject
	private LiveProgressReader liveReader;
	@Inject
	private TrainingGuideResolver training;
	@Inject
	private BoundedHttp http;
	@Inject
	private BrowserLinks browser;
	@Inject
	private SpriteManager spriteManager;
	@Inject
	private SkillIconManager skillIconManager;
	private volatile QuestCapeSession session;

	@Override
	protected void startUp()
	{
		if (session != null)
		{
			session.close();
		}
		session = new QuestCapeSession(clientThread, client, toolbar, guide, progress, liveReader, training, http,
			browser, spriteManager, skillIconManager);
	}

	@Override
	protected void shutDown()
	{
		QuestCapeSession previous = session;
		session = null;
		if (previous != null)
		{
			previous.close();
		}
	}

	private void withSession(java.util.function.Consumer<QuestCapeSession> action)
	{
		QuestCapeSession current = session;
		if (current != null && current.active())
		{
			action.accept(current);
		}
	}

	@Override
	public void syncPlayer()
	{
		withSession(current -> current.progress.syncPlayer());
	}

	@Override
	public void refresh()
	{
		withSession(current -> current.guide.refresh());
	}

	@Override
	public void training(String skill)
	{
		withSession(current -> current.links.training(skill));
	}

	@Override
	public void manual(String scope, GuideRow row, boolean checked)
	{
		withSession(current -> current.progress.manual(scope, row, checked));
	}

	@Override
	public void source(String url)
	{
		withSession(current -> current.links.source(url));
	}

	@Override
	public void report()
	{
		withSession(current -> current.links.report());
	}

	@Override
	public boolean copyLink(String url)
	{
		QuestCapeSession current = session;
		return current != null && current.active() && current.links.copyLink(url);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		withSession(current -> current.progress.onGameStateChanged(event));
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		withSession(current -> current.progress.onVarbitChanged(event));
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		withSession(current -> current.progress.onStatChanged(event));
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		withSession(current -> current.progress.onGameTick(event));
	}
}

package com.questcape.guide.classification;

import com.questcape.progress.activity.definitions.ActivityKey;
import com.questcape.progress.activity.definitions.BalloonDestination;
import com.questcape.progress.activity.definitions.DiaryKey;
import java.util.*;
import java.util.regex.*;

import static com.questcape.guide.interpretation.SourceTextNormalizer.normalize;

/** Source-side reviewed action aliases. Detectors never inspect Wiki text. */
public final class ActivityCatalog
{
	private static final Pattern DIARY_ACTION = Pattern.compile(
		"^(?:(?:complete|claim|collect|receive) (?:the )?)?(easy|medium|hard|elite) ([a-z &]+) diary(?: reward)?\\.?$");
	private static final String BALLOON_PREFIX = "unlock: balloon transport system to ";

	public static ActivityKey diary(String source)
	{
		String text = normalize(source);
		Matcher match = DIARY_ACTION.matcher(text);
		if (!match.matches())
		{
			return null;
		}
		DiaryKey.Tier tier = Arrays.stream(DiaryKey.Tier.values()).filter(t -> t.getSource().equals(match.group(1)))
			.findFirst().orElse(null);
		String region = match.group(2);
		DiaryKey.Region area = Arrays.stream(DiaryKey.Region.values()).filter(r -> region.equals(r.getSource())
			|| region.equals("kourend & kebos") && r == DiaryKey.Region.KOUREND
			|| region.equals("lumbridge & draynor") && r == DiaryKey.Region.LUMBRIDGE
			|| region.equals("western provinces") && r == DiaryKey.Region.WESTERN).findFirst().orElse(null);
		if (area == null || tier == null)
		{
			return null;
		}
		boolean reward = text.startsWith("claim ") || text.startsWith("collect ") || text.startsWith("receive ");
		return ActivityKey.diary(new DiaryKey(area, tier, reward ? DiaryKey.Action.REWARD : DiaryKey.Action.TASKS));
	}

	public static ActivityKey unlock(String source)
	{
		String text = normalize(source);
		if (text.startsWith(BALLOON_PREFIX))
		{
			for (BalloonDestination destination : BalloonDestination.values())
			{
				if (text.substring(BALLOON_PREFIX.length()).equals(destination.getSource()))
				{
					return ActivityKey.balloon(destination);
				}
			}
		}
		if (text.equals("unlock: stronghold of security"))
		{
			return ActivityKey.special(ActivityKey.Special.STRONGHOLD_COINS);
		}
		if (text.equals("unlock: museum camp"))
		{
			return ActivityKey.special(ActivityKey.Special.MUSEUM_CAMP_REWARD);
		}
		return null;
	}

	public static ActivityKey handIn(String source)
	{
		return normalize(source).startsWith("hand in the diary of herbi flax to the apothecary")
			? ActivityKey.special(ActivityKey.Special.HERBI_FLAX)
			: null;
	}

	public static boolean kudos(String source)
	{
		String value = normalize(source);
		return value.equals("unlock: varrock museum kudos") || value.equals("unlock: more varrock museum kudos");
	}

	public static ActivityKey rowId(String source, boolean reward)
	{
		String id = normalize(source);
		for (BalloonDestination destination : BalloonDestination.values())
		{
			if (id.equals(destination.getSource() + " balloon"))
			{
				return ActivityKey.balloon(destination);
			}
		}
		int split = id.indexOf('#');
		if (split > 0)
		{
			return diary((reward ? "claim " : "") + id.substring(split + 1) + " " + id.substring(0, split));
		}
		return null;
	}

	private ActivityCatalog()
	{
	}
}

package com.questcape.guide.classification;

import com.questcape.guide.interpretation.ProjectedLevelInterpreter;
import com.questcape.guide.interpretation.SkillMentionInterpreter;
import com.questcape.guide.model.ClassifiedAction;
import com.questcape.guide.model.GuideRow;
import com.questcape.guide.source.GuideFieldRole;
import com.questcape.guide.source.RowEvidence;
import com.questcape.guide.source.SourceRow;
import com.questcape.persistence.LegacyKeyCodec;
import java.util.*;

/** Producer/cache boundary: semantic work precedes immutable row construction. */
public final class GuideAssembler
{
	public static GuideRow source(SourceRow source)
	{
		return GuideClassifier.classify(source);
	}

	static GuideRow assemble(String key, SourceRow source, GuideRow.Kind kind, ClassifiedAction action)
	{
		Map<String, Integer> targets = new LinkedHashMap<>();
		if (!action.getTraining().isUnresolved())
		{
			action.getTraining().getTargets().forEach(target -> targets.put(target.getSkill(), target.getGoal()));
		}
		return create(key, source.getPosition(), kind, source.getTitle(), source.getWikiTarget(), targets,
			source.getFields(), source.getLinks(), source.getEvidence(), action);
	}

	public static GuideRow row(String key, int position, GuideRow.Kind kind, String title, String wiki, String quest,
		Map<String, Integer> targets, Map<String, String> fields, Map<String, String> links)
	{
		return row(key, position, kind, title, wiki, quest, targets, fields, links, null);
	}

	/** Explicit data-producer adapter; semantic preparation still has one central owner. */
	public static GuideRow row(String key, int position, GuideRow.Kind kind, String title, String wiki, String quest,
		Map<String, Integer> targets, Map<String, String> fields, Map<String, String> links, RowEvidence evidence)
	{
		return GuideClassifier.legacy(key, position, kind, title, wiki, quest, targets, fields, links, evidence);
	}

	public static GuideRow repeated(GuideRow original, String key, int position)
	{
		ClassifiedAction action = original.isManual()
			? ClassifiedAction.unknown(ClassifiedAction.Reason.UNSUPPORTED_ACTION)
			: original.action();
		return create(key, position, original.getKind(), original.getTitle(), original.getWikiTarget(),
			original.getTargets(), original.getFields(), original.getLinks(), original.getEvidence(), action);
	}

	static GuideRow create(String key, int position, GuideRow.Kind kind, String title, String wiki,
		Map<String, Integer> targets,
		Map<String, String> fields, Map<String, String> links, RowEvidence evidence, ClassifiedAction action)
	{
		List<GuideRow.Field> roles = new ArrayList<>();
		fields.forEach((label, value) ->
		{
			GuideFieldRole role = GuideFieldRole.of(label);
			roles.add(new GuideRow.Field(role, label, value, SkillMentionInterpreter.interpret(value),
				role == GuideFieldRole.PROJECTIONS ? ProjectedLevelInterpreter.interpret(value, evidence.spans(role))
					: List.of()));
		});
		return new GuideRow(key, position, kind, title, wiki,
			action.getQuest() == null ? null : LegacyKeyCodec.encode(action.getQuest()),
			action.getActivity() == null ? null : LegacyKeyCodec.encode(action.getActivity()), targets, fields, links,
			evidence, roles, action);
	}

	private GuideAssembler()
	{
	}
}

package com.questcape.guide.classification;

import com.questcape.guide.interpretation.SkillCatalog;
import com.questcape.guide.interpretation.TrainingInstruction;
import com.questcape.guide.interpretation.TrainingTargetInterpreter;
import com.questcape.guide.model.ClassifiedAction;
import com.questcape.guide.model.GuideRow;
import com.questcape.guide.source.RowEvidence;
import com.questcape.guide.source.SourceRow;
import com.questcape.persistence.LegacyKeyCodec;
import com.questcape.progress.activity.definitions.ActivityKey;
import com.questcape.progress.evaluation.CompletionPolicy;
import com.questcape.progress.model.QuestKey;
import java.util.*;
import java.util.regex.*;

import static com.questcape.guide.interpretation.SourceTextNormalizer.normalize;

/** Reconciles independent identity hints and explicit requested actions at one boundary. */
final class GuideClassifier
{
	private static final Pattern COMMENT = Pattern.compile(
		"^(?:note|tip|important|comment|reminder|recommendation)\\s*:|^(?:all|these|those|this|the following|from here|from this point|you can|you may|you have|you now|congratulations)\\b");
	private static final Pattern START = Pattern.compile("^(?:start miniquest:|start)\\s+");
	private static final Pattern FINISH = Pattern.compile("^(?:complete|finish)\\s+");

	static GuideRow classify(int position, String title, String wiki, Map<String, String> fields,
		Map<String, String> links, boolean fullWidth)
	{
		return classify(new SourceRow(position, title, wiki, fields, links, null, fullWidth));
	}

	static GuideRow classify(SourceRow source)
	{
		String text = normalize(source.getTitle());
		boolean start = START.matcher(text).find();
		Set<QuestKey> quests = new HashSet<>();
		addQuest(quests, QuestCatalog.quest(source.getWikiTarget()));
		addQuest(quests, QuestCatalog.quest(source.getTitle()));
		addQuest(quests, QuestCatalog.exact(source.attribute(RowEvidence.ROW_ID)));
		boolean reward = text.startsWith("claim ") || text.startsWith("collect ") || text.startsWith("receive ");
		Set<ActivityKey> activities = new HashSet<>();
		add(activities, ActivityCatalog.diary(source.getTitle()));
		add(activities, ActivityCatalog.unlock(source.getTitle()));
		add(activities, ActivityCatalog.handIn(source.getTitle()));
		ActivityKey id = ActivityCatalog.rowId(source.attribute(RowEvidence.ROW_ID), reward);
		if (id != null)
		{
			activities.add(id);
		}
		GuideRow.Kind kind;
		ClassifiedAction action;
		if (COMMENT.matcher(text).find()
			|| source.isFullWidth() && normalize(source.getWikiTarget()).equals("quest point cape"))
		{
			kind = GuideRow.Kind.INFORMATION;
			action = matched(CompletionPolicy.INFORMATION, null, null);
		}
		else if (text.startsWith("train "))
		{
			kind = GuideRow.Kind.TRAINING;
			TrainingInstruction training = reconcileTraining(TrainingTargetInterpreter.interpret(source.getTitle()),
				source);
			action = new ClassifiedAction(
				training.isUnresolved() ? ClassifiedAction.Outcome.UNSUPPORTED : ClassifiedAction.Outcome.MATCHED,
				training.isUnresolved() ? ClassifiedAction.Reason.UNSUPPORTED_TRAINING : ClassifiedAction.Reason.NONE,
				CompletionPolicy.TRAINING, null, null, training);
		}
		else if (quests.size() > 1 || activities.size() > 1 || !quests.isEmpty() && !activities.isEmpty())
		{
			kind = GuideRow.Kind.UNKNOWN;
			action = ClassifiedAction.unknown(ClassifiedAction.Reason.CONFLICTING_IDENTITY);
		}
		else if (!activities.isEmpty())
		{
			ActivityKey key = activities.iterator().next();
			kind = key.getDiary() != null ? GuideRow.Kind.DIARY
				: key.getSpecial() == ActivityKey.Special.HERBI_FLAX ? GuideRow.Kind.ACTIVITY : GuideRow.Kind.UNLOCK;
			boolean explicit = ActivityCatalog.diary(source.getTitle()) != null
				|| ActivityCatalog.unlock(source.getTitle()) != null
				|| ActivityCatalog.handIn(source.getTitle()) != null
				|| id != null && (text.startsWith("unlock ") || FINISH.matcher(text).find() || reward);
			action = explicit ? matched(CompletionPolicy.ACTIVITY, null, key)
				: ClassifiedAction.unknown(ClassifiedAction.Reason.UNSUPPORTED_ACTION);
		}
		else if (!quests.isEmpty())
		{
			QuestKey quest = quests.iterator().next();
			boolean mini = text.contains("(miniquest)") || text.startsWith("start miniquest:")
				|| quest.getExtra() != null;
			kind = mini ? GuideRow.Kind.MINIQUEST : GuideRow.Kind.QUEST;
			// A reviewed bare quest is an explicit whole-quest instruction; unfamiliar verbs do not imply finish.
			boolean bare = QuestCatalog.exact(
				source.getTitle().replaceAll("(?i)\\s*\\(miniquest\\)", "").replaceAll("\\.$", "").trim()) != null;
			boolean canonicalLink = QuestCatalog.exact(source.getWikiTarget()) != null
				&& text.equals(normalize(source.getWikiTarget()));
			action = start || FINISH.matcher(text).find() || bare || canonicalLink
				? matched(start ? CompletionPolicy.QUEST_START : CompletionPolicy.QUEST_FINISH, quest, null)
				: new ClassifiedAction(ClassifiedAction.Outcome.UNSUPPORTED, ClassifiedAction.Reason.UNSUPPORTED_ACTION,
					CompletionPolicy.UNKNOWN, quest, null, TrainingInstruction.empty());
		}
		else if (ActivityCatalog.kudos(source.getTitle()))
		{
			kind = GuideRow.Kind.UNLOCK;
			action = matched(CompletionPolicy.MANUAL_KUDOS, null, null);
		}
		else
		{
			kind = text.contains("(miniquest)") ? GuideRow.Kind.MINIQUEST
				: text.contains("diary") && !text.startsWith("hand in") ? GuideRow.Kind.DIARY
					: text.startsWith("unlock") ? GuideRow.Kind.UNLOCK
						: text.startsWith("hand in") || text.startsWith("claim") ? GuideRow.Kind.ACTIVITY
							: GuideRow.Kind.UNKNOWN;
			action = ClassifiedAction.unknown(ClassifiedAction.Reason.UNSUPPORTED_ACTION);
		}
		String quest = action.getQuest() == null ? null : LegacyKeyCodec.encode(action.getQuest());
		return GuideAssembler.assemble(
			LegacyKeyCodec.row(kind, quest, start, source.getWikiTarget(), source.getTitle()), source, kind, action);
	}

	/** Legacy callers already supply category/operands; prepare them only at this input boundary. */
	static GuideRow legacy(String key, int position, GuideRow.Kind kind, String title, String wiki, String quest,
		Map<String, Integer> targets, Map<String, String> fields, Map<String, String> links, RowEvidence evidence)
	{
		TrainingInstruction training = kind == GuideRow.Kind.TRAINING ? TrainingTargetInterpreter.interpret(title)
			: TrainingInstruction.empty();
		if (kind == GuideRow.Kind.TRAINING && training.getTargets().isEmpty() && !targets.isEmpty())
		{
			List<TrainingInstruction.Target> retained = new ArrayList<>();
			boolean unresolved = false;
			for (Map.Entry<String, Integer> entry : targets.entrySet())
			{
				String skill = SkillCatalog.identity(entry.getKey());
				if (entry.getValue() != null && SkillCatalog.validLevel(skill, entry.getValue()))
				{
					retained.add(new TrainingInstruction.Target(skill, null, entry.getValue()));
				}
				else
				{
					unresolved = true;
				}
			}
			training = new TrainingInstruction(Collections.unmodifiableList(retained), training.getTokens(),
				unresolved || retained.isEmpty());
		}
		QuestKey questKey = LegacyKeyCodec.quest(quest);
		ActivityKey activity = kind == GuideRow.Kind.DIARY ? ActivityCatalog.diary(title)
			: kind == GuideRow.Kind.UNLOCK ? ActivityCatalog.unlock(title)
				: kind == GuideRow.Kind.ACTIVITY ? ActivityCatalog.handIn(title) : null;
		CompletionPolicy policy = kind == GuideRow.Kind.INFORMATION ? CompletionPolicy.INFORMATION
			: questKey != null ? CompletionPolicy.QUEST_FINISH
				: kind == GuideRow.Kind.TRAINING ? CompletionPolicy.TRAINING
					: activity != null ? CompletionPolicy.ACTIVITY
						: kind == GuideRow.Kind.UNLOCK && ActivityCatalog.kudos(title) && !LegacyKeyCodec.repeated(key)
							? CompletionPolicy.MANUAL_KUDOS
							: CompletionPolicy.UNKNOWN;
		ClassifiedAction action = new ClassifiedAction(
			policy == CompletionPolicy.UNKNOWN ? ClassifiedAction.Outcome.UNSUPPORTED
				: ClassifiedAction.Outcome.MATCHED,
			policy == CompletionPolicy.UNKNOWN ? ClassifiedAction.Reason.UNSUPPORTED_ACTION
				: ClassifiedAction.Reason.NONE,
			policy, questKey, activity, training);
		return GuideAssembler.create(key, position, kind, title, wiki, targets, fields, links,
			evidence == null ? new RowEvidence(Collections.emptyMap()) : evidence, action);
	}

	private static TrainingInstruction reconcileTraining(TrainingInstruction parsed, SourceRow source)
	{
		String skill = SkillCatalog.identity(source.attribute(RowEvidence.SKILL)),
			raw = source.attribute(RowEvidence.LEVEL);
		if (skill == null || raw.isBlank() || raw.length() > SkillCatalog.MAX_LEVEL_DIGITS
			|| !raw.chars().allMatch(Character::isDigit))
		{
			return parsed;
		}
		int level = Integer.parseInt(raw);
		if (!SkillCatalog.validLevel(skill, level))
		{
			return parsed;
		}
		boolean compatible = parsed.getTargets().stream()
			.anyMatch(target -> target.getSkill().equals(skill) && target.getGoal() == level);
		return compatible ? parsed : new TrainingInstruction(parsed.getTargets(), parsed.getTokens(), true);
	}

	private static ClassifiedAction matched(CompletionPolicy policy, QuestKey quest, ActivityKey activity)
	{
		return new ClassifiedAction(ClassifiedAction.Outcome.MATCHED, ClassifiedAction.Reason.NONE, policy, quest,
			activity, TrainingInstruction.empty());
	}

	private static void add(Set<ActivityKey> values, ActivityKey key)
	{
		if (key != null)
		{
			values.add(key);
		}
	}

	private static void addQuest(Set<QuestKey> values, String token)
	{
		QuestKey quest = LegacyKeyCodec.quest(token);
		if (quest != null)
		{
			values.add(quest);
		}
	}

	private GuideClassifier()
	{
	}
}

package com.questcape.guide.classification;

import java.util.*;
import net.runelite.api.Quest;

import static com.questcape.guide.interpretation.SourceTextNormalizer.normalize;

public final class QuestCatalog
{
	private static final Map<String, String> QUESTS = new HashMap<>();
	static
	{
		for (Quest quest : Quest.values())
		{
			register(quest.getName(), quest.name());
		}
		register("natural history quiz", com.questcape.progress.model.QuestKey.Extra.NATURAL_HISTORY_QUIZ.getToken());
		register("knight waves training grounds", com.questcape.progress.model.QuestKey.Extra.KNIGHT_WAVES.getToken());
		alias("Recipe for Disaster/Freeing the Mountain Dwarf", "Recipe for Disaster - Mountain Dwarf");
		alias("Recipe for Disaster/Freeing the Goblin generals", "Recipe for Disaster - Wartface & Bentnoze");
		alias("Recipe for Disaster/Freeing Pirate Pete", "Recipe for Disaster - Pirate Pete");
		alias("Recipe for Disaster/Freeing the Lumbridge Guide", "Recipe for Disaster - Lumbridge Guide");
		alias("Recipe for Disaster/Freeing Evil Dave", "Recipe for Disaster - Evil Dave");
		alias("Recipe for Disaster/Freeing Skrach Uglogwee", "Recipe for Disaster - Skrach Uglogwee");
		alias("Recipe for Disaster/Freeing Sir Amik Varze", "Recipe for Disaster - Sir Amik Varze");
		alias("Recipe for Disaster/Freeing King Awowogei", "Recipe for Disaster - King Awowogei");
		alias("Recipe for Disaster/Another Cook's Quest", "Recipe for Disaster - Another Cook's Quest");
		alias("Recipe for Disaster/Defeating the Culinaromancer", "Recipe for Disaster - Culinaromancer");
	}

	private QuestCatalog()
	{
	}

	private static void alias(String source, String target)
	{
		String id = QUESTS.get(normalize(target));
		if (id != null)
		{
			register(source, id);
		}
	}

	public static String quest(String title)
	{
		String exact = QUESTS.get(normalize(title));
		if (exact != null)
		{
			return exact;
		}
		String name = normalize(title).replaceAll("^(?:start miniquest:|start|complete|finish)\\s+", "")
			.replace("(miniquest)", "").trim();
		String identity = QUESTS.get(name);
		return identity == null ? QUESTS.get(name.replaceAll("\\.$", "")) : identity;
	}

	public static String exact(String source)
	{
		return QUESTS.get(normalize(source));
	}

	private static void register(String alias, String identity)
	{
		String previous = QUESTS.putIfAbsent(normalize(alias), identity);
		if (previous != null && !previous.equals(identity))
		{
			throw new IllegalStateException("Conflicting quest alias");
		}
	}
}

package com.questcape.guide.interpretation;

import com.questcape.guide.source.RowEvidence;
import java.util.*;
import lombok.Value;
import net.runelite.api.Skill;

/** Projected source levels are presentation data. Any unparsed annotation retains the raw field. */
public final class ProjectedLevelInterpreter
{
	@Value
	public static class Entry
	{
		int level;
		Skill skill;
	}

	public static List<Entry> interpret(String source)
	{
		List<SourceTextTokenizer.Token> tokens = SourceTextTokenizer.words(source);
		List<Entry> result = new ArrayList<>();
		int at = 0;
		while (at < tokens.size())
		{
			String number = tokens.get(at++).getText();
			if (number.equals(",") || number.equals(";"))
			{
				continue;
			}
			if (number.length() > SkillCatalog.MAX_LEVEL_DIGITS || !number.chars().allMatch(Character::isDigit)
				|| at >= tokens.size())
			{
				return List.of();
			}
			String identity = SkillCatalog.identity(tokens.get(at++).getText());
			int level = Integer.parseInt(number);
			if (identity == null || SkillCatalog.COMBAT.equals(identity) || !SkillCatalog.validLevel(identity, level))
			{
				return List.of();
			}
			result.add(new Entry(level, Skill.valueOf(identity)));
		}
		return Collections.unmodifiableList(result);
	}

	public static List<Entry> interpret(String source, List<RowEvidence.SkillSpan> spans)
	{
		List<Entry> structured = new ArrayList<>();
		StringJoiner text = new StringJoiner(" ");
		for (RowEvidence.SkillSpan span : spans)
		{
			List<Entry> entries = interpret(span.getText());
			if (entries.size() != 1 || !entries.get(0).getSkill().name().equals(SkillCatalog.identity(span.getSkill())))
			{
				return interpret(source);
			}
			structured.addAll(entries);
			text.add(span.getText());
		}
		return !structured.isEmpty()
			&& SourceTextNormalizer.normalize(text.toString()).equals(SourceTextNormalizer.normalize(source))
				? Collections.unmodifiableList(structured)
				: interpret(source);
	}

	private ProjectedLevelInterpreter()
	{
	}
}

package com.questcape.guide.interpretation;

import java.util.*;
import java.util.regex.Pattern;
import java.util.stream.Collectors;
import net.runelite.api.Experience;
import net.runelite.api.Skill;

import static com.questcape.guide.interpretation.SourceTextNormalizer.normalize;

/** One local vocabulary for source skill mentions; combat is a derived target. */
public final class SkillCatalog
{
	public static final String COMBAT = "COMBAT";
	private static final String OVERALL = "OVERALL";
	public static final int MIN_LEVEL = 1, MAX_SKILL_LEVEL = Experience.MAX_REAL_LEVEL,
		MAX_COMBAT_LEVEL = Experience.MAX_COMBAT_LEVEL, MAX_LEVEL_DIGITS = 3;
	private static final List<String> NAMES = new ArrayList<>();
	static
	{
		Arrays.stream(Skill.values()).map(Skill::getName).forEach(NAMES::add);
		NAMES.add("Runecrafting");
		NAMES.add("Defense");
	}

	private SkillCatalog()
	{
	}

	public static String identity(String name)
	{
		String normalized = normalize(name);
		if (normalized.equals("combat"))
		{
			return COMBAT;
		}
		if (normalized.equals("runecrafting"))
		{
			normalized = "runecraft";
		}
		if (normalized.equals("defense"))
		{
			normalized = "defence";
		}
		for (Skill skill : Skill.values())
		{
			if (normalize(skill.getName()).equals(normalized))
			{
				return skill.name();
			}
		}
		return null;
	}

	public static String namesPattern()
	{
		return NAMES.stream().sorted(Comparator.comparingInt(String::length).reversed())
			.map(Pattern::quote).collect(Collectors.joining("|"));
	}

	public static List<TrainingInstruction.Token> tokens(String source)
	{
		return SkillMentionInterpreter.interpret(source);
	}

	public static boolean validLevel(String skill, int level)
	{
		String identity = identity(skill);
		return identity != null && !OVERALL.equals(identity) && level >= MIN_LEVEL
			&& level <= (COMBAT.equals(identity) ? MAX_COMBAT_LEVEL : MAX_SKILL_LEVEL);
	}
}

package com.questcape.guide.interpretation;

import java.util.*;

/** Decoration preserves original offsets; it never creates completion requirements. */
public final class SkillMentionInterpreter
{
	public static List<TrainingInstruction.Token> interpret(String source)
	{
		List<TrainingInstruction.Token> result = new ArrayList<>();
		for (SourceTextTokenizer.Token token : SourceTextTokenizer.words(source))
		{
			String identity = SkillCatalog.identity(token.getText());
			if (identity != null && !SkillCatalog.COMBAT.equals(identity))
			{
				result.add(new TrainingInstruction.Token(token.getStart(), token.getEnd(), identity));
			}
		}
		return Collections.unmodifiableList(result);
	}

	private SkillMentionInterpreter()
	{
	}
}

