/**
 * Guide source evidence, parsing, interpretation, classification, immutable values and repository state.
 * See docs/package-layout.md for ownership and change-entry points; subfolders match Java packages.
 */
package com.questcape.guide;

package com.questcape.guide.parsing;

import com.questcape.guide.classification.GuideAssembler;
import com.questcape.guide.interpretation.SkillCatalog;
import com.questcape.guide.model.GuideRow;
import com.questcape.guide.model.GuideSnapshot;
import com.questcape.guide.source.GuideFieldRole;
import com.questcape.guide.source.GuideSourcePolicy;
import com.questcape.guide.source.RowEvidence;
import com.questcape.guide.source.SourceRow;
import com.questcape.progress.compatibility.ActivityProgress;
import com.questcape.progress.compatibility.Identities;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.util.*;
import javax.inject.Inject;

public class GuideParser
{
	private static final String CAPTION = GuideSourcePolicy.CAPTION;
	private static final List<String> HEADERS = Arrays.asList("Quest/Activity", "Quick Guide", "New levels after quest",
		"Quest points", "Total QP", "Additional info", "Location");

	@Inject
	public GuideParser()
	{
	}

	public List<GuideRow> parse(String html) throws IOException
	{
		if (html == null || html.length() > GuideSourcePolicy.MAX_CONTENT)
		{
			throw new IOException("Guide response exceeds limits");
		}
		HtmlTree.Node document = HtmlTree.parse(html);
		List<HtmlTree.Node> candidates = new ArrayList<>();
		for (HtmlTree.Node table : document.all("table"))
		{
			if (table.children("caption").stream().anyMatch(c -> Identities.normalize(c.text()).equals(CAPTION)))
			{
				candidates.add(table);
			}
		}
		if (candidates.size() != 1)
		{
			throw new IOException("Expected one captioned guide table; found " + candidates.size());
		}
		List<HtmlTree.Node> physical = candidates.get(0).all("tr");
		if (physical.size() < GuideSourcePolicy.MIN_ROWS || physical.size() > GuideSourcePolicy.MAX_ROWS)
		{
			throw new IOException("Guide table is empty or oversized");
		}
		Map<Integer, Span> spans = new HashMap<>();
		List<GuideRow> rows = new ArrayList<>();
		List<String> headers = null;
		for (HtmlTree.Node tr : physical)
		{
			List<HtmlTree.Node> cells = new ArrayList<>();
			for (Object child : tr.content)
			{
				if (child instanceof HtmlTree.Node)
				{
					HtmlTree.Node node = (HtmlTree.Node)child;
					if (node.tag.equals("td") || node.tag.equals("th"))
					{
						cells.add(node);
					}
				}
			}
			if (cells.isEmpty())
			{
				continue;
			}
			HtmlTree.Node[] grid = new HtmlTree.Node[GuideSourcePolicy.COLUMNS];
			for (Iterator<Map.Entry<Integer, Span>> it = spans.entrySet().iterator(); it.hasNext();)
			{
				Map.Entry<Integer, Span> entry = it.next();
				grid[entry.getKey()] = entry.getValue().node;
				if (--entry.getValue().remaining == 0)
				{
					it.remove();
				}
			}
			int column = 0;
			for (HtmlTree.Node cell : cells)
			{
				while (column < GuideSourcePolicy.COLUMNS && grid[column] != null)
				{
					column++;
				}
				int colspan = span(cell, "colspan"), rowspan = span(cell, "rowspan");
				if (column + colspan > GuideSourcePolicy.COLUMNS)
				{
					throw new IOException("Unexpected guide column count");
				}
				for (int j = 0; j < colspan; j++)
				{
					if (grid[column] != null)
					{
						throw new IOException("Overlapping merged cells");
					}
					grid[column] = cell;
					if (rowspan > 1)
					{
						spans.put(column, new Span(cell, rowspan - 1));
					}
					column++;
				}
			}
			if (Arrays.stream(grid).anyMatch(Objects::isNull))
			{
				throw new IOException("Incomplete guide row");
			}
			if (headers == null)
			{
				headers = new ArrayList<>();
				for (HtmlTree.Node cell : grid)
				{
					headers.add(cell.text());
				}
				for (String header : HEADERS)
				{
					if (headers.stream().noneMatch(h -> GuideFieldRole.of(h) == GuideFieldRole.of(header)))
					{
						throw new IOException("Guide headers changed: " + headers);
					}
				}
				continue;
			}
			Map<String, String> fields = new LinkedHashMap<>(), links = new LinkedHashMap<>();
			for (int j = 0; j < GuideSourcePolicy.COLUMNS; j++)
			{
				fields.put(headers.get(j), grid[j].text());
			}
			for (HtmlTree.Node anchor : tr.all("a"))
			{
				String href = safeWikiLink(anchor.attr("href"));
				if (href != null && !anchor.text().isEmpty())
				{
					links.put(href, anchor.text());
				}
			}
			HtmlTree.Node titleCell = grid[headers.indexOf(
				headers.stream().filter(h -> GuideFieldRole.of(h) == GuideFieldRole.TITLE).findFirst().get())];
			String title = titleCell.text();
			if (title.isBlank())
			{
				throw new IOException("Empty guide action");
			}
			String wikiTarget = "";
			for (HtmlTree.Node a : titleCell.all("a"))
			{
				String href = safeWikiLink(a.attr("href"));
				if (href != null && !a.text().isBlank())
				{
					wikiTarget = wikiTitle(href);
					break;
				}
			}
			boolean fullWidth = Arrays.stream(grid).allMatch(cell -> cell == titleCell);
			Map<GuideFieldRole, Map<String, String>> cellLinks = new EnumMap<>(GuideFieldRole.class);
			Map<GuideFieldRole, List<RowEvidence.SkillSpan>> skillSpans = new EnumMap<>(GuideFieldRole.class);
			for (int j = 0; j < grid.length; j++)
			{
				Map<String, String> destinations = new LinkedHashMap<>();
				for (HtmlTree.Node anchor : grid[j].all("a"))
				{
					String safe = safeWikiLink(anchor.attr("href"));
					if (safe != null && !anchor.text().isBlank())
					{
						destinations.put(safe, anchor.text());
						links.putIfAbsent(safe, anchor.text());
					}
				}
				if (!fullWidth)
				{
					cellLinks.put(GuideFieldRole.of(headers.get(j)), destinations);
				}
				List<RowEvidence.SkillSpan> mentions = new ArrayList<>();
				for (HtmlTree.Node span : grid[j].all("span"))
				{
					String skill = SkillCatalog.identity(span.attr(RowEvidence.SKILL));
					if (skill != null && span.text().length() <= GuideSourcePolicy.ATTRIBUTE_LENGTH)
					{
						mentions.add(new RowEvidence.SkillSpan(skill, span.text()));
					}
				}
				if (!mentions.isEmpty() && (!fullWidth || j == 0))
				{
					skillSpans.put(fullWidth ? GuideFieldRole.TITLE : GuideFieldRole.of(headers.get(j)),
						List.copyOf(mentions));
				}
			}
			rows.add(classify(rows.size(), title, wikiTarget, fields, links, fullWidth,
				new RowEvidence(cellLinks, tr.attrs, skillSpans)));
		}
		if (!spans.isEmpty() || rows.isEmpty())
		{
			throw new IOException("Truncated guide table");
		}
		return distinguishRepeatedRows(rows);
	}

	/** Upgrade cached classifications offline; the stored field layout identifies full-width rows. */
	public GuideSnapshot reclassify(GuideSnapshot snapshot)
	{
		List<GuideRow> rows = new ArrayList<>();
		for (GuideRow row : snapshot.getRows())
		{
			boolean fullWidth = row.getFields().values().stream().allMatch(row.getTitle()::equals);
			rows.add(classify(row.getPosition(), row.getTitle(), row.getWikiTarget(),
				row.getFields(), row.getLinks(), fullWidth, row.getEvidence()));
		}
		return new GuideSnapshot(snapshot.getRevision(), snapshot.getRetrievedAt(), snapshot.getValidatedAt(),
			snapshot.getEtag(), snapshot.getLastModified(), distinguishRepeatedRows(rows));
	}

	/** Repair older truncated balloon titles only when retained validated links identify one destination. */
	private static GuideRow classify(int position, String title, String wikiTarget,
		Map<String, String> fields, Map<String, String> links, boolean fullWidth, RowEvidence evidence)
	{
		if (Identities.normalize(title).equals("unlock: balloon transport system to"))
		{
			Set<String> destinations = new LinkedHashSet<>();
			for (String url : links.keySet())
			{
				String safe = safeWikiLink(url);
				if (safe != null)
				{
					String candidate = "Unlock: Balloon transport system to " + wikiTitle(safe);
					if (ActivityProgress.unlock(candidate) != null)
					{
						destinations.add(candidate);
					}
				}
			}
			if (destinations.size() == 1)
			{
				String oldTitle = title;
				title = destinations.iterator().next();
				Map<String, String> repaired = new LinkedHashMap<>(fields);
				String repairedTitle = title;
				repaired.replaceAll((key, value) -> value.equals(oldTitle) ? repairedTitle : value);
				fields = repaired;
			}
		}
		return GuideAssembler.source(new SourceRow(position, title, wikiTarget, fields, links, evidence, fullWidth));
	}

	private static List<GuideRow> distinguishRepeatedRows(List<GuideRow> rows)
	{
		// Keep even identical repetitions visible, but never share a manual check between indistinguishable actions.
		Map<String, Long> counts = rows.stream()
			.collect(java.util.stream.Collectors.groupingBy(GuideRow::getKey, java.util.stream.Collectors.counting()));
		Map<String, Integer> occurrences = new HashMap<>();
		for (int i = 0; i < rows.size(); i++)
		{
			GuideRow row = rows.get(i);
			if (counts.get(row.getKey()) > 1)
			{
				String key = com.questcape.persistence.LegacyKeyCodec.repeated(row.getKey(),
					occurrences.merge(row.getKey(), 1, Integer::sum));
				rows.set(i, GuideAssembler.repeated(row, key, i));
			}
		}
		return rows;
	}

	private static int span(HtmlTree.Node node, String name) throws IOException
	{
		if (node.attr(name).isEmpty())
		{
			return 1;
		}
		try
		{
			int value = Integer.parseInt(node.attr(name));
			if (value < 1 || value > GuideSourcePolicy.MAX_SPAN)
			{
				throw new NumberFormatException();
			}
			return value;
		}
		catch (NumberFormatException e)
		{
			throw new IOException("Invalid merged cell", e);
		}
	}

	private static final class Span
	{
		final HtmlTree.Node node;
		int remaining;

		Span(HtmlTree.Node node, int remaining)
		{
			this.node = node;
			this.remaining = remaining;
		}
	}

	public static String safeWikiLink(String href)
	{
		try
		{
			URI uri = URI.create(GuideSnapshot.SOURCE).resolve(href);
			if (!GuideSourcePolicy.SECURE_SCHEME.equalsIgnoreCase(uri.getScheme())
				|| !GuideSourcePolicy.HOST.equalsIgnoreCase(uri.getHost())
				|| uri.getUserInfo() != null || (uri.getPort() != -1 && uri.getPort() != GuideSourcePolicy.SECURE_PORT))
			{
				return null;
			}
			uri = uri.normalize();
			return URI.create(GuideSourcePolicy.SECURE_ORIGIN + (uri.getRawPath() == null ? "" : uri.getRawPath())
				+ (uri.getRawQuery() == null ? "" : "?" + uri.getRawQuery())
				+ (uri.getRawFragment() == null ? "" : "#" + uri.getRawFragment())).toASCIIString();
		}
		catch (IllegalArgumentException e)
		{
			return null;
		}
	}

	private static String wikiTitle(String validatedUrl)
	{
		return URI.create(validatedUrl).getPath().replaceFirst("^/w/", "").replace('_', ' ');
	}

	public static String digest(String value)
	{
		try
		{
			byte[] bytes = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
			StringBuilder out = new StringBuilder();
			for (byte b : bytes)
			{
				out.append(String.format("%02x", b));
			}
			return out.toString();
		}
		catch (NoSuchAlgorithmException e)
		{
			throw new IllegalStateException(e);
		}
	}
}

package com.questcape.guide.parsing;

import java.io.*;
import java.util.*;
import javax.swing.text.*;
import javax.swing.text.html.*;
import javax.swing.text.html.parser.ParserDelegator;

/** Inert DOM built with the JDK parser; no browser, remote image loads or extra Hub dependency. */
final class HtmlTree
{
	static final class Node
	{
		final String tag;
		final Map<String, String> attrs = new HashMap<>();
		final List<Object> content = new ArrayList<>();
		Node parent;

		Node(String tag)
		{
			this.tag = tag;
		}

		String attr(String key)
		{
			return attrs.getOrDefault(key, "");
		}

		List<Node> children(String tag)
		{
			List<Node> result = new ArrayList<>();
			for (Object item : content)
			{
				if (item instanceof Node && ((Node)item).tag.equals(tag))
				{
					result.add((Node)item);
				}
			}
			return result;
		}

		List<Node> all(String tag)
		{
			List<Node> result = new ArrayList<>();
			for (Object item : content)
			{
				if (item instanceof Node)
				{
					Node node = (Node)item;
					if (node.tag.equals(tag))
					{
						result.add(node);
					}
					result.addAll(node.all(tag));
				}
			}
			return result;
		}

		String text()
		{
			if (Arrays.asList("script", "style", "iframe", "object").contains(tag))
			{
				return "";
			}
			StringBuilder out = new StringBuilder();
			for (Object part : content)
			{
				out.append(part instanceof Node ? ((Node)part).text() : part).append(' ');
			}
			return out.toString().replace('\u00a0', ' ').trim().replaceAll("\\s+", " ");
		}
	}

	static Node parse(String html) throws IOException
	{
		Node root = new Node("root");
		new ParserDelegator().parse(new StringReader(html), new HTMLEditorKit.ParserCallback()
		{
			Node current = root;

			Node add(HTML.Tag tag, MutableAttributeSet attrs)
			{
				Node node = new Node(tag.toString());
				Enumeration<?> names = attrs.getAttributeNames();
				while (names.hasMoreElements())
				{
					Object name = names.nextElement();
					node.attrs.put(name.toString(), String.valueOf(attrs.getAttribute(name)));
				}
				node.parent = current;
				current.content.add(node);
				return node;
			}

			@Override
			public void handleStartTag(HTML.Tag t, MutableAttributeSet a, int p)
			{
				current = add(t, a);
			}

			@Override
			public void handleSimpleTag(HTML.Tag t, MutableAttributeSet a, int p)
			{
				add(t, a);
			}

			@Override
			public void handleEndTag(HTML.Tag t, int p)
			{
				for (Node n = current; n != root; n = n.parent)
				{
					if (n.tag.equals(t.toString()))
					{
						current = n.parent;
						break;
					}
				}
			}

			@Override
			public void handleText(char[] data, int p)
			{
				current.content.add(new String(data));
			}
		}, true);
		return root;
	}
}

package com.questcape.guide.repository;

import com.google.gson.*;
import com.questcape.guide.model.GuideRow;
import com.questcape.guide.model.GuideSnapshot;
import com.questcape.guide.parsing.GuideParser;
import com.questcape.guide.source.GuideSourcePolicy;
import com.questcape.integration.http.BoundedHttp;
import com.questcape.integration.http.HttpPolicy;
import com.questcape.persistence.CachePolicy;
import com.questcape.persistence.JsonStore;
import com.questcape.persistence.StoredView;
import com.questcape.persistence.StoredView.SaveState;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import javax.inject.*;
import lombok.extern.slf4j.Slf4j;

@Singleton
@Slf4j
public class GuideRepository
{
	public static final String ENDPOINT = "https://oldschool.runescape.wiki/api.php?action=parse&page=Optimal_quest_guide&prop=text%7Crevid&format=json";
	public static final long MAX_AGE = TimeUnit.HOURS.toMillis(24);
	private final GuideParser parser;
	private final BoundedHttp http;
	private final JsonStore store;
	private volatile GuideSnapshot snapshot;
	private volatile StoredView<GuideSnapshot> published = StoredView.empty();
	private long nextRefresh;
	private CompletableFuture<GuideSnapshot> pending;
	private long generation;
	private final Object persistenceLock = new Object();
	private volatile String persistenceStatus = "";
	private boolean unreadable;

	@Inject
	public GuideRepository(GuideParser parser, BoundedHttp http, JsonStore store)
	{
		this.parser = parser;
		this.http = http;
		this.store = store;
	}

	public synchronized long token()
	{
		return generation;
	}

	public GuideSnapshot load() throws IOException
	{
		return load(token());
	}

	public GuideSnapshot load(long token) throws IOException
	{
		synchronized (this)
		{
			checkActive(token);
		}
		synchronized (persistenceLock)
		{
			GuideSnapshot saved;
			try
			{
				saved = prepare(store.read(CachePolicy.GUIDE, CachePolicy.STANDARD_ROUTE, GuideSnapshot.class));
				unreadable = false;
			}
			catch (IOException e)
			{
				unreadable = true;
				throw e;
			}
			if (saved != null)
			{
				synchronized (this)
				{
					if (token == generation)
					{
						snapshot = saved;
						published = new StoredView<>(saved, SaveState.SAVED);
					}
				}
			}
		}
		return snapshot;
	}

	public StoredView<GuideSnapshot> view()
	{
		return published;
	}

	public GuideSnapshot current()
	{
		return snapshot;
	}

	public String persistenceStatus()
	{
		return persistenceStatus;
	}

	public boolean isStale(long now)
	{
		return snapshot == null || now - snapshot.getValidatedAt() >= MAX_AGE;
	}

	public CompletableFuture<GuideSnapshot> refresh(Executor executor, long now)
	{
		return refresh(executor, now, token());
	}

	public synchronized CompletableFuture<GuideSnapshot> refresh(Executor executor, long now, long expected)
	{
		if (expected != generation)
		{
			return CompletableFuture
				.failedFuture(new java.util.concurrent.CancellationException("Invalidated guide authority"));
		}
		if (pending != null && !pending.isDone())
		{
			return pending;
		}
		if (now < nextRefresh)
		{
			return CompletableFuture.failedFuture(new IOException("Guide refresh cooldown; retry shortly"));
		}
		nextRefresh = now + CachePolicy.GUIDE_COOLDOWN_MILLIS;
		long token = generation;
		pending = CompletableFuture.supplyAsync(() ->
		{
			try
			{
				GuideSnapshot previous = snapshot;
				Map<String, String> headers = new HashMap<>();
				if (previous != null)
				{
					if (previous.getEtag() != null)
					{
						headers.put(HttpPolicy.IF_NONE_MATCH, previous.getEtag());
					}
					if (previous.getLastModified() != null)
					{
						headers.put(HttpPolicy.IF_MODIFIED_SINCE, previous.getLastModified());
					}
				}
				BoundedHttp.Result response = http.get(ENDPOINT, headers, GuideSourcePolicy.MAX_CONTENT);
				GuideSnapshot candidate;
				long received = System.currentTimeMillis();
				if (response.getCode() == HttpPolicy.NOT_MODIFIED && previous != null)
				{
					candidate = previous.revalidated(received);
				}
				else
				{
					if (response.getCode() != HttpPolicy.OK)
					{
						throw new IOException("Wiki returned HTTP " + response.getCode());
					}
					JsonObject parse = new JsonParser().parse(response.getBody()).getAsJsonObject()
						.getAsJsonObject(GuideSourcePolicy.RESPONSE_PARSE);
					if (parse == null || !parse.has(GuideSourcePolicy.RESPONSE_TEXT))
					{
						throw new IOException("Wiki parse response is missing content");
					}
					String html = parse.getAsJsonObject(GuideSourcePolicy.RESPONSE_TEXT)
						.get(GuideSourcePolicy.RESPONSE_HTML).getAsString();
					String revision = parse.has(GuideSourcePolicy.RESPONSE_REVISION)
						? parse.get(GuideSourcePolicy.RESPONSE_REVISION).getAsString()
						: null;
					// The JDK parser repairs HTML, so independently require complete source table termination.
					if (!html.toLowerCase(Locale.ROOT).contains("</table>"))
					{
						throw new IOException("Unterminated guide table");
					}
					candidate = new GuideSnapshot(revision, received, received, response.getEtag(),
						response.getLastModified(), parser.parse(html));
					validate(candidate, previous);
				}
				synchronized (persistenceLock)
				{
					synchronized (this)
					{
						checkActive(token);
					}
					SaveState saveState = SaveState.SAVED;
					try
					{
						if (unreadable)
						{
							prepare(store.read(CachePolicy.GUIDE, CachePolicy.STANDARD_ROUTE, GuideSnapshot.class));
							unreadable = false;
						}
						store.write(CachePolicy.GUIDE, CachePolicy.STANDARD_ROUTE, candidate);
					}
					catch (IOException e)
					{
						saveState = SaveState.UNSAVED;
						log.debug("QuestCape guide cache write failed ({})", e.getClass().getSimpleName());
					}
					synchronized (this)
					{
						checkActive(token);
						snapshot = candidate;
						published = new StoredView<>(candidate, saveState);
						persistenceStatus = saveState == SaveState.UNSAVED ? "Route unsaved; cache unavailable. Refresh to retry." : "";
					}
				}
				return candidate;
			}
			catch (IOException | RuntimeException e)
			{
				throw new CompletionException(e);
			}
		}, executor);
		return pending;
	}

	private GuideSnapshot prepare(GuideSnapshot saved) throws IOException
	{
		if (saved == null)
		{
			return null;
		}
		validate(saved, null);
		try
		{
			return parser.reclassify(saved);
		}
		catch (RuntimeException malformed)
		{
			throw new IOException("Invalid guide enrichment; original retained", malformed);
		}
	}

	private void checkActive(long token) throws InterruptedIOException
	{
		if (token != generation || Thread.currentThread().isInterrupted())
		{
			throw new InterruptedIOException("Refresh canceled");
		}
	}

	public synchronized void cancel()
	{
		generation++;
		if (pending != null)
		{
			pending.cancel(true);
		}
	}

	public static void validate(GuideSnapshot candidate, GuideSnapshot previous) throws IOException
	{
		if (candidate.getSchema() != GuideSnapshot.SCHEMA || !GuideSnapshot.SOURCE.equals(candidate.getSource())
			|| candidate.getRows() == null || candidate.getRows().isEmpty()
			|| candidate.getRows().size() > GuideSourcePolicy.MAX_ROWS
			|| candidate.getRetrievedAt() <= 0 || candidate.getValidatedAt() <= 0)
		{
			throw new IOException("Invalid guide cache");
		}
		for (GuideRow row : candidate.getRows())
		{
			if (row == null || row.getKey() == null || row.getTitle() == null || row.getTitle().isBlank()
				|| row.getWikiTarget() == null
				|| row.getKind() == null || row.getFields() == null
				|| row.getFields().size() != GuideSourcePolicy.COLUMNS
				|| row.getTargets() == null
				|| row.getLinks() == null)
			{
				throw new IOException("Invalid guide row");
			}
			if (row.getFields().entrySet().stream().anyMatch(field -> field.getKey() == null || field.getValue() == null)
				|| row.getLinks().entrySet().stream().anyMatch(link -> link.getKey() == null || link.getValue() == null)
				|| row.getTargets().entrySet().stream().anyMatch(target -> target.getKey() == null || target.getValue() == null))
			{
				throw new IOException("Invalid guide field data; original retained");
			}
		}
		if (previous != null
			&& candidate.getRows().size() < previous.getRows().size() * GuideSourcePolicy.MIN_RETAINED_ROW_RATIO)
		{
			throw new IOException("Suspicious guide truncation; keeping the last valid revision");
		}
	}
}

package com.questcape.guide.source;

import com.questcape.progress.compatibility.Identities;
import java.util.Arrays;

/** Source header aliases are interpreted once, independently of display copy. */
public enum GuideFieldRole
{
	TITLE("Quest/Activity"), QUICK_GUIDE("Quick Guide"), PROJECTIONS("New levels after quest", "New levels"),
	QUEST_POINTS("Quest points"), GUIDE_QP("Total QP"), ADVICE("Additional info", "Additional information"),
	LOCATION("Location"), UNKNOWN();

	private final String[] aliases;

	GuideFieldRole(String... aliases)
	{
		this.aliases = aliases;
	}

	public static GuideFieldRole of(String header)
	{
		for (GuideFieldRole role : values())
		{
			if (Arrays.stream(role.aliases)
				.anyMatch(alias -> Identities.normalize(alias).equals(Identities.normalize(header))))
			{
				return role;
			}
		}
		return UNKNOWN;
	}
}

package com.questcape.guide.source;

/** Source shape limits and the reviewed Wiki transport host. */
public final class GuideSourcePolicy
{
	public static final double MIN_RETAINED_ROW_RATIO = 0.8;
	public static final String RESPONSE_PARSE = "parse", RESPONSE_TEXT = "text", RESPONSE_HTML = "*",
		RESPONSE_REVISION = "revid", CAPTION = "old school runescape quest guide";
	public static final String HOST = "oldschool.runescape.wiki", SECURE_SCHEME = "https",
		SECURE_ORIGIN = "https://oldschool.runescape.wiki";
	public static final int MAX_CONTENT = 4_000_000, MIN_ROWS = 2, MAX_ROWS = 2000, COLUMNS = 7, MAX_SPAN = 100,
		SECURE_PORT = 443, ATTRIBUTE_LENGTH = 256;

	private GuideSourcePolicy()
	{
	}
}

package com.questcape.guide.source;

import com.questcape.guide.interpretation.SkillCatalog;
import com.questcape.guide.model.GuideRow;
import com.questcape.guide.parsing.GuideParser;
import com.questcape.progress.compatibility.Identities;
import java.net.URI;
import java.util.*;
import lombok.Value;

/** Optional additive schema-1 enrichment: safe cell links, allowlisted attributes and source skill spans. */
@Value
public class RowEvidence
{
	public static final int VERSION = 2;
	public static final String ROW_ID = "data-rowid", SKILL = "data-skill", LEVEL = "data-skill-level";
	private static final int MAX_ATTRIBUTE_LENGTH = GuideSourcePolicy.ATTRIBUTE_LENGTH;
	int version;
	Map<String, String> attributes;
	Map<GuideFieldRole, List<SkillSpan>> skillSpans;

	@Value
	public static class SkillSpan
	{
		String skill;
		String text;
	}

	Map<GuideFieldRole, Map<String, String>> cellLinks;

	public RowEvidence(Map<GuideFieldRole, Map<String, String>> links)
	{
		this(links, Collections.emptyMap());
	}

	public RowEvidence(Map<GuideFieldRole, Map<String, String>> links, Map<String, String> attrs)
	{
		this(links, attrs, Collections.emptyMap());
	}

	public RowEvidence(Map<GuideFieldRole, Map<String, String>> links, Map<String, String> attrs,
		Map<GuideFieldRole, List<SkillSpan>> spans)
	{
		version = VERSION;
		Map<GuideFieldRole, List<SkillSpan>> retained = new EnumMap<>(GuideFieldRole.class);
		spans.forEach((role, values) -> retained.put(role, List.copyOf(values)));
		skillSpans = Collections.unmodifiableMap(retained);
		Map<String, String> sanitized = new LinkedHashMap<>();
		for (String name : List.of(ROW_ID, SKILL, LEVEL))
		{
			String value = attrs.get(name);
			if (value != null && value.length() <= MAX_ATTRIBUTE_LENGTH
				&& value.codePoints().noneMatch(Character::isISOControl))
			{
				sanitized.put(name, value);
			}
		}
		attributes = Collections.unmodifiableMap(sanitized);
		Map<GuideFieldRole, Map<String, String>> copy = new EnumMap<>(GuideFieldRole.class);
		links.forEach((role, values) -> copy.put(role, Collections.unmodifiableMap(new LinkedHashMap<>(values))));
		cellLinks = Collections.unmodifiableMap(copy);
	}

	public List<SkillSpan> spans(GuideFieldRole role)
	{
		if (version != VERSION || skillSpans == null || skillSpans.get(role) == null)
		{
			return List.of();
		}
		List<SkillSpan> safe = new ArrayList<>();
		for (SkillSpan span : skillSpans.get(role))
		{
			if (span != null && SkillCatalog.identity(span.getSkill()) != null && span.getText() != null
				&& span.getText().length() <= MAX_ATTRIBUTE_LENGTH)
			{
				safe.add(span);
			}
		}
		return Collections.unmodifiableList(safe);
	}

	public String attribute(String name)
	{
		if (version != VERSION || attributes == null)
		{
			return "";
		}
		String value = attributes.get(name);
		return value != null && value.length() <= MAX_ATTRIBUTE_LENGTH
			&& value.codePoints().noneMatch(Character::isISOControl) ? value : "";
	}

	public Map<String, String> links(GuideFieldRole role, Map<String, String> retained)
	{
		Map<String, String> result = new LinkedHashMap<>();
		Map<String, String> canonical = new LinkedHashMap<>();
		retained.forEach((url, label) ->
		{
			String safe = GuideParser.safeWikiLink(url);
			if (safe != null)
			{
				canonical.putIfAbsent(safe, label);
			}
		});
		if ((version == VERSION || version == 1) && cellLinks != null && cellLinks.get(role) != null)
		{
			cellLinks.get(role).forEach((url, label) ->
			{
				String safe = GuideParser.safeWikiLink(url);
				if (safe != null && canonical.containsKey(safe))
				{
					result.put(safe, canonical.get(safe));
				}
			});
		}
		return Collections.unmodifiableMap(result);
	}

	public static Map<String, String> resolve(GuideFieldRole role, GuideRow row)
	{
		if (role == GuideFieldRole.QUICK_GUIDE && row.sourceFields().stream().noneMatch(field -> field.getRole() == role
			&& !field.getValue().isBlank() && !field.getValue().equals(row.getTitle())
			&& !Identities.normalize(field.getValue()).equals("n/a")))
		{
			return Collections.emptyMap();
		}
		RowEvidence evidence = row.getEvidence();
		if (evidence != null && (evidence.version == VERSION || evidence.version == 1) && evidence.cellLinks != null
			&& evidence.cellLinks.containsKey(role))
		{
			return evidence.links(role, row.getLinks());
		}
		Map<String, String> result = new LinkedHashMap<>();
		List<GuideRow.Field> fields = row.sourceFields();
		String value = fields.stream()
			.filter(field -> field.getRole() == role && !field.getValue().equals(row.getTitle()))
			.map(GuideRow.Field::getValue).findFirst().orElse("");
		row.getLinks().forEach((url, label) ->
		{
			String safe = GuideParser.safeWikiLink(url);
			if (safe == null)
			{
				return;
			}
			URI uri = URI.create(safe);
			String page = uri.getPath().replaceFirst("^/w/", "").replace('_', ' ');
			if (role == GuideFieldRole.QUICK_GUIDE && !value.isBlank() && !Identities.normalize(value).equals("n/a")
				&& page.toLowerCase(Locale.ROOT).endsWith("/quick guide")
				&& Identities.normalize(page.substring(0, page.lastIndexOf('/')))
					.equals(Identities.normalize(row.getWikiTarget())))
			{
				result.put(safe, label);
			}
			if (role == GuideFieldRole.LOCATION && !value.isBlank()
				&& Identities.normalize(value).equals(Identities.normalize(label)))
			{
				result.put(safe, label);
			}
			if (role == GuideFieldRole.TITLE && uri.getFragment() == null && uri.getQuery() == null
				&& !row.getWikiTarget().isBlank()
				&& Identities.normalize(page).equals(Identities.normalize(row.getWikiTarget())))
			{
				result.put(safe, label);
			}
		});
		return role == GuideFieldRole.LOCATION && result.size() != 1 ? Collections.emptyMap()
			: Collections.unmodifiableMap(result);
	}
}

