package com.questcape.integration;

import com.questcape.guide.model.GuideRow;
import com.questcape.guide.repository.GuideRepository;
import com.questcape.integration.coordination.GuideRefreshCoordinator;
import com.questcape.integration.coordination.ProgressCoordinator;
import com.questcape.integration.http.BoundedHttp;
import com.questcape.integration.lifecycle.PluginRun;
import com.questcape.integration.links.BrowserLinks;
import com.questcape.integration.links.TrainingGuideResolver;
import com.questcape.integration.links.TrainingLinkController;
import com.questcape.progress.capture.LiveProgressReader;
import com.questcape.progress.tracking.ProgressService;
import com.questcape.ui.GuideActions;
import com.questcape.ui.sidebar.SidebarController;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.BiConsumer;
import net.runelite.api.Client;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.*;
import net.runelite.client.ui.ClientToolbar;

/** Composition root for one enabled run. It owns no capture, completion or widget algorithms. */
public final class QuestCapeSession implements AutoCloseable
{
	private final PluginRun run;
	public final ProgressCoordinator progress;
	public final GuideRefreshCoordinator guide;
	public final TrainingLinkController links;

	public QuestCapeSession(ClientThread clientThread, Client client, ClientToolbar toolbar, GuideRepository repository,
		ProgressService progressService,
		LiveProgressReader reader, TrainingGuideResolver training, BoundedHttp http, BrowserLinks browser,
		SpriteManager sprites, SkillIconManager skills)
	{
		run = new PluginRun();
		try
		{
			run.own(repository::cancel);
			run.own(http::cancel);
			AtomicReference<SidebarController> target = new AtomicReference<>();
			Runnable render = () ->
			{
				SidebarController view = target.get();
				if (view != null)
				{
					view.render();
				}
			};
			BiConsumer<Long, String> message = (authority, text) ->
			{
				SidebarController view = target.get();
				if (view != null)
				{
					view.message(authority, text);
				}
			};
			progress = new ProgressCoordinator(run, clientThread, client, progressService, reader, render, message);
			run.own(progress::close);
			guide = new GuideRefreshCoordinator(run, repository, render);
			links = new TrainingLinkController(run, training, browser, progress::authority, message);
			GuideActions actions = new GuideActions()
			{
				public void syncPlayer()
				{
					progress.syncPlayer();
				}

				public void refresh()
				{
					guide.refresh();
				}

				public void training(String skill)
				{
					links.training(skill);
				}

				public void manual(String scope, GuideRow row, boolean checked)
				{
					progress.manual(scope, row, checked);
				}

				public void source(String url)
				{
					links.source(url);
				}

				public void report()
				{
					links.report();
				}

				public boolean copyLink(String url)
				{
					return links.copyLink(url);
				}
			};
			SidebarController sidebar = new SidebarController(run, toolbar, sprites, skills, repository,
				progressService, progress, guide, training, actions);
			target.set(sidebar);
			run.own(sidebar::close);
			sidebar.start();
			guide.start();
		}
		catch (RuntimeException failure)
		{
			run.close();
			throw failure;
		}
	}

	public boolean active()
	{
		return run.active();
	}

	@Override
	public void close()
	{
		run.close();
	}
}

package com.questcape.integration.coordination;

import com.questcape.guide.repository.GuideRepository;
import com.questcape.integration.OperationOutcome;
import com.questcape.integration.OperationOutcome.State;
import com.questcape.integration.lifecycle.PluginRun;
import java.io.IOException;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicReference;

/** Guide request lifecycle and its typed outcome, tied to the original enabled run. */
public final class GuideRefreshCoordinator
{
	private final PluginRun run;
	private final GuideRepository guide;
	private final long authority;
	private final Runnable render;
	private final AtomicReference<OperationOutcome> status;

	public GuideRefreshCoordinator(PluginRun run, GuideRepository guide, Runnable render)
	{
		this.run = run;
		this.guide = guide;
		this.render = render;
		this.authority = guide.token();
		status = new AtomicReference<>(new OperationOutcome(run.id(), -1, State.IDLE, ""));
	}

	public OperationOutcome status()
	{
		return status.get();
	}

	public void start()
	{
		run.work(() ->
		{
			try
			{
				guide.load(authority);
				outcome(State.IDLE, "");
			}
			catch (IOException | RuntimeException failure)
			{
				outcome(State.FAILED, failure.getMessage());
			}
			if (run.active() && guide.isStale(System.currentTimeMillis()))
			{
				refresh();
			}
		});
	}

	public void refresh()
	{
		if (!run.active())
		{
			return;
		}
		outcome(State.RUNNING, "");
		try
		{
			guide.refresh(run.network(), System.currentTimeMillis(), authority).whenComplete((snapshot, failure) ->
			{
				if (run.active())
				{
					outcome(failure == null ? State.IDLE : State.FAILED,
						failure == null ? "" : "Refresh failed: " + cause(failure));
				}
			});
		}
		catch (RejectedExecutionException failure)
		{
			outcome(State.FAILED, "Request queue is busy.");
		}
	}

	private void outcome(State state, String detail)
	{
		if (run.active())
		{
			status.set(new OperationOutcome(run.id(), -1, state, detail));
			render.run();
		}
	}

	private static String cause(Throwable failure)
	{
		while (failure.getCause() != null)
		{
			failure = failure.getCause();
		}
		return failure.getMessage();
	}
}

package com.questcape.integration.coordination;

import com.questcape.guide.model.GuideRow;
import com.questcape.integration.OperationOutcome;
import com.questcape.integration.OperationOutcome.State;
import com.questcape.integration.lifecycle.PluginRun;
import com.questcape.progress.capture.LiveProgressReader;
import com.questcape.progress.model.AccountProgress;
import com.questcape.progress.tracking.ProgressService;
import java.io.*;
import java.util.concurrent.atomic.*;
import java.util.function.BiConsumer;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.client.callback.ClientThread;

/** ClientThread readiness/capture and scoped immutable handoff to the run's serial worker. */
public final class ProgressCoordinator
{
	private static final long CLOSED_SESSION = -1;
	private static final String QUEUE_BUSY = "Work queue is busy. Retry shortly.",
		NOT_READY = "Log in and wait for your character to be ready before syncing.",
		ALREADY_SYNCING = "A character sync is already running. Retry shortly.",
		CHARACTER_CHANGED = "Character changed or is not ready. Wait for the next game tick and retry.",
		RESYNCING = "Resyncing progress…", SAVE_FAILED = "Could not save character progress",
		CAPTURE_UNAVAILABLE = "Character progress is not ready yet. Retry after the next game tick.";
	private final PluginRun run;
	private final ClientThread clientThread;
	private final Client client;
	private final ProgressService progress;
	private final LiveProgressReader liveReader;
	private final Runnable changed;
	private final BiConsumer<Long, String> message;
	private final AtomicLong liveGeneration = new AtomicLong();
	private final AtomicLong serviceSession;
	private final AtomicBoolean livePending = new AtomicBoolean();
	private final AtomicReference<OperationOutcome> progressStatus;
	private volatile boolean ready, dirty = true;

	public ProgressCoordinator(PluginRun run, ClientThread clientThread, Client client, ProgressService progress,
		LiveProgressReader liveReader, Runnable changed, BiConsumer<Long, String> message)
	{
		this.run = run;
		this.clientThread = clientThread;
		this.client = client;
		this.progress = progress;
		this.liveReader = liveReader;
		this.changed = changed;
		this.message = message;
		serviceSession = new AtomicLong(progress.token());
		progressStatus = new AtomicReference<>(new OperationOutcome(run.id(), 0, State.IDLE, ""));
	}

	public boolean ready()
	{
		return ready;
	}

	public long authority()
	{
		return liveGeneration.get();
	}

	public OperationOutcome status()
	{
		return progressStatus.get();
	}

	public void syncPlayer()
	{
		syncPlayer(run.id());
	}

	public void manual(String scope, GuideRow row, boolean checked)
	{
		manual(run.id(), scope, row, checked);
	}

	private boolean valid(long token)
	{
		return run.active() && token == run.id();
	}

	private boolean work(long token, Runnable action)
	{
		boolean accepted = valid(token) && run.work(action);
		if (!accepted && valid(token))
		{
			show(token, authority(), QUEUE_BUSY);
		}
		return accepted;
	}

	private void show(long token, long account, String value)
	{
		if (valid(token))
		{
			message.accept(account, value);
		}
	}

	private void show(String value)
	{
		show(run.id(), authority(), value);
	}

	private void render(long token)
	{
		if (valid(token))
		{
			changed.run();
		}
	}

	private void render()
	{
		render(run.id());
	}

	private void outcome(AtomicReference<OperationOutcome> holder, long token, long account, State state, String detail)
	{
		OperationOutcome previous = holder.get();
		if (valid(token) && account == authority())
		{
			holder.compareAndSet(previous, new OperationOutcome(token, account, state, detail));
		}
	}

	private void syncPlayer(long life)
	{
		if (!valid(life))
		{
			return;
		}
		long accountToken = liveGeneration.get();
		AccountProgress expected = progress.current();
		clientThread.invokeLater(() ->
		{
			if (!valid(life) || accountToken != liveGeneration.get())
			{
				return;
			}
			if (!ready || expected == null || client.getGameState() != GameState.LOGGED_IN)
			{
				show(life, accountToken, NOT_READY);
				return;
			}
			captureProgress(life, accountToken, true, expected.getScope());
		});
	}

	private void manual(long token, String scope, GuideRow row, boolean checked)
	{
		long accountToken = liveGeneration.get();
		long session = serviceSession.get();
		work(token, () ->
		{
			try
			{
				if (accountToken != liveGeneration.get())
				{
					return;
				}
				progress.toggleManual(scope, row, checked, session);
			}
			catch (IOException e)
			{
				show(token, accountToken, e.getMessage());
			}
			render(token);
		});
	}

	public void onGameStateChanged(GameStateChanged event)
	{
		if (!run.active())
		{
			return;
		}
		dirty = true;
		GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING || state == GameState.CONNECTION_LOST)
		{
			ready = false;
			liveGeneration.incrementAndGet();
			invalidateSession();
			livePending.set(false);
			progressStatus.set(new OperationOutcome(run.id(), liveGeneration.get(), State.IDLE, ""));
			show("");
			render();
		}
		if (state == GameState.LOGGED_IN)
		{
			ready = false;
		}
	}

	public void onVarbitChanged(VarbitChanged event)
	{
		dirty = true;
	}

	public void onStatChanged(StatChanged event)
	{
		dirty = true;
	}

	public void onGameTick(GameTick event)
	{
		if (!run.active() || client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		ready = true;
		if (!dirty)
		{
			return;
		}
		captureProgress(run.id(), liveGeneration.get(), false, null);
	}

	private void captureProgress(long life, long accountToken, boolean explicit, String expectedScope)
	{
		if (!livePending.compareAndSet(false, true))
		{
			if (explicit)
			{
				show(life, accountToken, ALREADY_SYNCING);
			}
			return;
		}
		dirty = false;
		long session = serviceSession.get();
		try
		{
			AccountProgress observation = liveReader.read();
			if (observation == null || (expectedScope != null && !expectedScope.equals(observation.getScope())))
			{
				dirty = true;
				livePending.set(false);
				if (explicit)
				{
					show(life, accountToken, CHARACTER_CHANGED);
				}
				return;
			}
			if (explicit)
			{
				outcome(progressStatus, life, accountToken, State.RUNNING, RESYNCING);
				render(life);
			}
			if (!work(life, () ->
			{
				try
				{
					if (!valid(life) || accountToken != liveGeneration.get())
					{
						return;
					}
					AccountProgress previous = progress.current();
					boolean newAccount = previous == null || !previous.getScope().equals(observation.getScope());
					if (!progress.acceptLive(observation, session, explicit))
					{
						return;
					}
					if (!valid(life) || accountToken != liveGeneration.get())
					{
						return;
					}
					if (newAccount)
					{
						show(life, accountToken, "");
					}
					outcome(progressStatus, life, accountToken, State.IDLE, "");
					render(life);
				}
				catch (IOException e)
				{
					if (valid(life) && accountToken == liveGeneration.get())
					{
						dirty = true;
						outcome(progressStatus, life, accountToken, State.FAILED, SAVE_FAILED);
						show(life, accountToken, e.getMessage());
						render(life);
					}
				}
				finally
				{
					if (valid(life) && accountToken == liveGeneration.get())
					{
						livePending.set(false);
					}
				}
			}))
			{
				dirty = true;
				livePending.set(false);
				outcome(progressStatus, life, accountToken, State.FAILED, QUEUE_BUSY);
			}
		}
		catch (RuntimeException e)
		{
			dirty = true;
			livePending.set(false);
			show(life, accountToken, CAPTURE_UNAVAILABLE);
		}
	}

	private void invalidateSession()
	{
		long expected = serviceSession.get();
		if (expected >= 0 && progress.logoutIfSession(expected))
		{
			serviceSession.compareAndSet(expected, expected + 1);
		}
	}

	public void close()
	{
		ready = false;
		liveGeneration.incrementAndGet();
		livePending.set(false);
		long expected = serviceSession.getAndSet(CLOSED_SESSION);
		if (expected >= 0)
		{
			progress.logoutIfSession(expected);
		}
	}

}

package com.questcape.integration.http;

import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import javax.inject.*;
import lombok.Value;
import okhttp3.*;

@Singleton
public class BoundedHttp
{
	private final OkHttpClient client;
	private final PluginMetadata.Loader metadata;
	private final Set<Call> calls = ConcurrentHashMap.newKeySet();
	private final java.util.concurrent.atomic.AtomicLong generation = new java.util.concurrent.atomic.AtomicLong();

	public BoundedHttp(OkHttpClient client)
	{
		this(client, new PluginMetadata.Loader());
	}

	@Inject
	public BoundedHttp(OkHttpClient client, PluginMetadata.Loader metadata)
	{
		this.metadata = metadata;
		this.client = client.newBuilder().connectTimeout(HttpPolicy.CONNECT_SECONDS, TimeUnit.SECONDS)
			.readTimeout(HttpPolicy.READ_SECONDS, TimeUnit.SECONDS)
			.callTimeout(HttpPolicy.CALL_SECONDS, TimeUnit.SECONDS)
			.followRedirects(false).followSslRedirects(false).retryOnConnectionFailure(false).build();
	}

	@Value
	public static class Result
	{
		int code;
		String body;
		String etag;
		String lastModified;
		String location;
		String retryAfter;
	}

	public Result get(String url, Map<String, String> headers, int maxBytes) throws IOException
	{
		long token = generation.get();
		if (Thread.currentThread().isInterrupted())
		{
			throw new InterruptedIOException("Request canceled");
		}
		Call call = client.newCall(request(url, headers));
		calls.add(call);
		if (generation.get() != token || Thread.currentThread().isInterrupted())
		{
			call.cancel();
		}
		try (Response response = call.execute())
		{
			ResponseBody body = response.body();
			String content = "";
			if (response.code() != HttpPolicy.NOT_MODIFIED)
			{
				if (body.contentLength() > maxBytes)
				{
					throw new IOException("Response too large");
				}
				byte[] bytes = body.byteStream().readNBytes(maxBytes + 1);
				if (bytes.length > maxBytes)
				{
					throw new IOException("Response too large");
				}
				content = new String(bytes, java.nio.charset.StandardCharsets.UTF_8);
			}
			return new Result(response.code(), content, response.header(HttpPolicy.ETAG),
				response.header(HttpPolicy.LAST_MODIFIED),
				response.header(HttpPolicy.LOCATION), response.header(HttpPolicy.RETRY_AFTER));
		}
		finally
		{
			calls.remove(call);
		}
	}

	public Request request(String url, Map<String, String> headers) throws IOException
	{
		Request.Builder request = new Request.Builder().url(url);
		headers.forEach(request::header);
		return request.header(HttpPolicy.USER_AGENT, metadata.get().getUserAgent()).build();
	}

	public void cancel()
	{
		generation.incrementAndGet();
		calls.forEach(Call::cancel);
	}
}

package com.questcape.integration.http;

/** Bounded transport policy and protocol names; no account information belongs in request identity. */
public final class HttpPolicy
{
	public static final int CONNECT_SECONDS = 10, READ_SECONDS = 20, CALL_SECONDS = 30, NOT_MODIFIED = 304, OK = 200,
		REDIRECT_MIN = 300, REDIRECT_MAX = 399, MAX_REDIRECTS = 5;
	public static final String USER_AGENT = "User-Agent", ETAG = "ETag", LAST_MODIFIED = "Last-Modified",
		LOCATION = "Location", RETRY_AFTER = "Retry-After", IF_NONE_MATCH = "If-None-Match",
		IF_MODIFIED_SINCE = "If-Modified-Since";

	private HttpPolicy()
	{
	}
}

package com.questcape.integration.http;

import java.io.*;
import java.util.*;
import java.util.function.Supplier;
import javax.inject.*;

/** Authoritative immutable product identity, also usable from an isolated distribution JAR. */
public final class PluginMetadata
{
	public static final String RESOURCE = "/com/questcape/plugin.properties";
	private static final String DISPLAY_NAME = "displayName", VERSION = "version", COMPANION = " (RuneLite companion)";
	private final String displayName, version, userAgent;

	private PluginMetadata(Properties values) throws IOException
	{
		displayName = required(values, DISPLAY_NAME);
		version = required(values, VERSION);
		if (!version.matches("[0-9]+\\.[0-9]+\\.[0-9]+(?:[-+][A-Za-z0-9.-]+)?"))
		{
			throw new MetadataException("Invalid plugin version metadata");
		}
		String token = displayName.replaceAll("[^A-Za-z0-9!#$%&'*+.^_`|~-]+", "-");
		if (token.isBlank() || token.chars().allMatch(value -> value == '-'))
		{
			throw new MetadataException("Invalid plugin product metadata");
		}
		userAgent = token + "/" + version + COMPANION;
	}

	public String getDisplayName()
	{
		return displayName;
	}

	public String getVersion()
	{
		return version;
	}

	public String getUserAgent()
	{
		return userAgent;
	}

	public static PluginMetadata read(InputStream input) throws IOException
	{
		if (input == null)
		{
			throw new MetadataException("Plugin metadata resource is unavailable");
		}
		try (InputStream owned = input)
		{
			Properties values = new Properties();
			values.load(owned);
			return new PluginMetadata(values);
		}
	}

	private static String required(Properties values, String name) throws IOException
	{
		String value = values.getProperty(name);
		if (value == null || value.isBlank() || value.chars().anyMatch(c -> c < 32 || c > 126))
		{
			throw new MetadataException("Missing or unsafe plugin metadata: " + name);
		}
		return value.trim();
	}

	public static final class MetadataException extends IOException
	{
		MetadataException(String message)
		{
			super(message);
		}
	}

	/** First use is on the HTTP worker, never during injection or a lifecycle/EDT callback. */
	@Singleton
	public static class Loader
	{
		private final Supplier<InputStream> resource;
		private PluginMetadata loaded;
		private IOException failure;
		private boolean attempted;

		@Inject
		public Loader()
		{
			this(() -> PluginMetadata.class.getResourceAsStream(RESOURCE));
		}

		public Loader(Supplier<InputStream> resource)
		{
			this.resource = Objects.requireNonNull(resource);
		}

		public synchronized PluginMetadata get() throws IOException
		{
			if (!attempted)
			{
				attempted = true;
				try
				{
					loaded = read(resource.get());
				}
				catch (IOException e)
				{
					failure = e;
				}
				catch (RuntimeException e)
				{
					failure = new IOException("Plugin metadata could not be read", e);
				}
			}
			if (failure != null)
			{
				throw failure;
			}
			return loaded;
		}
	}
}

package com.questcape.integration.lifecycle;

import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import lombok.extern.slf4j.Slf4j;

/** Owns only resources and original enablement authority, never domain or widget state. */
@Slf4j
public final class PluginRun implements AutoCloseable
{
	private static final int STATE_WORKERS = 1, NETWORK_WORKERS = 2, QUEUE_CAPACITY = 16;
	private static final AtomicLong NEXT_ID = new AtomicLong();
	private final long id = NEXT_ID.incrementAndGet();
	private final AtomicBoolean active = new AtomicBoolean(true);
	private final List<Runnable> cleanup = new ArrayList<>();
	private final ThreadPoolExecutor state, network;

	public PluginRun()
	{
		state = executor("questcape-state", STATE_WORKERS);
		try
		{
			network = executor("questcape-http", NETWORK_WORKERS);
		}
		catch (RuntimeException failure)
		{
			state.shutdownNow();
			throw failure;
		}
	}

	private static ThreadPoolExecutor executor(String name, int threads)
	{
		return new ThreadPoolExecutor(threads, threads, 0, TimeUnit.SECONDS, new ArrayBlockingQueue<>(QUEUE_CAPACITY),
			task ->
			{
				Thread worker = new Thread(task, name);
				worker.setDaemon(true);
				return worker;
			}, new ThreadPoolExecutor.AbortPolicy());
	}

	public long id()
	{
		return id;
	}

	public boolean active()
	{
		return active.get();
	}

	public Executor network()
	{
		return network;
	}

	public boolean work(Runnable task)
	{
		return submit(state, task);
	}

	public boolean network(Runnable task)
	{
		return submit(network, task);
	}

	private boolean submit(Executor executor, Runnable task)
	{
		if (!active())
		{
			return false;
		}
		try
		{
			executor.execute(() ->
			{
				if (active())
				{
					task.run();
				}
			});
			return true;
		}
		catch (RejectedExecutionException failure)
		{
			return false;
		}
	}

	public void own(Runnable release)
	{
		synchronized (cleanup)
		{
			if (active())
			{
				cleanup.add(release);
				return;
			}
		}
		release.run();
	}

	@Override
	public void close()
	{
		if (!active.compareAndSet(true, false))
		{
			return;
		}
		state.shutdownNow();
		network.shutdownNow();
		List<Runnable> acquired;
		synchronized (cleanup)
		{
			acquired = new ArrayList<>(cleanup);
			cleanup.clear();
		}
		Collections.reverse(acquired);
		for (Runnable release : acquired)
		{
			try
			{
				release.run();
			}
			catch (RuntimeException failure)
			{
				log.debug("QuestCape resource cleanup failed ({})", failure.getClass().getSimpleName());
			}
		}
	}
}

