package com.questcape.integration.links;

import com.questcape.integration.http.BoundedHttp;
import com.questcape.integration.http.HttpPolicy;
import com.questcape.progress.compatibility.Identities;
import java.io.*;
import java.net.URI;
import java.util.*;
import javax.inject.*;

@Singleton
public class TrainingGuideResolver
{
	private static final String RESOURCE = "/theoatrix.properties", HOST = "theoatrix.net",
		WWW_HOST = "www.theoatrix.net";
	public static final String FALLBACK = "https://www.theoatrix.net/all-guides";
	private volatile Map<String, String> urls = Collections.emptyMap();
	private boolean prepared;
	private final BoundedHttp http;

	@Inject
	public TrainingGuideResolver(BoundedHttp http)
	{
		this.http = http;
	}

	/** Worker-only local resource preparation, before sidebar publication; resolution itself performs no IO. */
	public synchronized void prepare() throws IOException
	{
		if (prepared)
		{
			return;
		}
		Properties definitions = new Properties();
		try (InputStream in = TrainingGuideResolver.class.getResourceAsStream(RESOURCE))
		{
			if (in == null)
			{
				throw new IOException("Missing packaged training links");
			}
			definitions.load(in);
		}
		Map<String, String> values = new HashMap<>();
		definitions.stringPropertyNames().forEach(name -> values.put(name, definitions.getProperty(name)));
		urls = Collections.unmodifiableMap(values);
		prepared = true;
	}

	public String resolve(String skill)
	{
		String id = Identities.skill(skill);
		String candidate = urls.getOrDefault(id == null ? "" : id, FALLBACK);
		return safe(candidate) ? candidate : FALLBACK;
	}

	public String label(String skill)
	{
		return resolve(skill).equals(FALLBACK) ? "Browse Theoatrix guides"
			: skill.replace('_', ' ') + " · Theoatrix guide";
	}

	public static boolean safe(String value)
	{
		try
		{
			URI uri = URI.create(value);
			return "https".equalsIgnoreCase(uri.getScheme()) && (HOST.equalsIgnoreCase(uri.getHost())
				|| WWW_HOST.equalsIgnoreCase(uri.getHost())) && uri.getUserInfo() == null
				&& (uri.getPort() == -1 || uri.getPort() == com.questcape.guide.source.GuideSourcePolicy.SECURE_PORT);
		}
		catch (IllegalArgumentException e)
		{
			return false;
		}
	}

	/** Validate every redirect before browser navigation. Runs only after user activation, off the EDT. */
	public String verifyDestination(String url) throws IOException
	{
		for (int redirects = 0; redirects < HttpPolicy.MAX_REDIRECTS; redirects++)
		{
			if (!safe(url))
			{
				throw new IOException("Unsafe training destination. Use Browse Theoatrix guides.");
			}
			BoundedHttp.Result response = http.get(url, Collections.emptyMap(),
				com.questcape.guide.source.GuideSourcePolicy.MAX_CONTENT);
			if (response.getCode() == HttpPolicy.OK)
			{
				return url;
			}
			if (response.getCode() < HttpPolicy.REDIRECT_MIN || response.getCode() > HttpPolicy.REDIRECT_MAX
				|| response.getLocation() == null)
			{
				throw new IOException(
					"Theoatrix returned HTTP " + response.getCode() + ". Retry or copy the guide link.");
			}
			try
			{
				url = URI.create(url).resolve(response.getLocation()).toString();
			}
			catch (IllegalArgumentException e)
			{
				throw new IOException("Invalid training redirect", e);
			}
		}
		throw new IOException("Too many training-guide redirects.");
	}
}

package com.questcape.integration.links;

import com.questcape.guide.parsing.GuideParser;
import com.questcape.integration.lifecycle.PluginRun;
import java.io.IOException;
import java.util.function.*;
import javax.swing.SwingUtilities;

/** Explicit browser actions and bounded asynchronous destination verification, scoped to one run. */
public final class TrainingLinkController
{
	private static final String CHECKING = "Checking Theoatrix destination…",
		QUEUE_BUSY = "Request queue is busy. Retry shortly.",
		RETRY = " · Click the training action to retry. Browse Theoatrix guides: ", LINK = " Link: ";
	private final PluginRun run;
	private final TrainingGuideResolver resolver;
	private final BrowserLinks browser;
	private final LongSupplier account;
	private final BiConsumer<Long, String> message;

	public TrainingLinkController(PluginRun run, TrainingGuideResolver resolver, BrowserLinks browser,
		LongSupplier account, BiConsumer<Long, String> message)
	{
		this.run = run;
		this.resolver = resolver;
		this.browser = browser;
		this.account = account;
		this.message = message;
	}

	public void training(String skill)
	{
		if (!run.active())
		{
			return;
		}
		String url = resolver.resolve(skill);
		long authority = account.getAsLong();
		message.accept(authority, CHECKING);
		if (!run.network(() ->
		{
			try
			{
				if (!current(authority))
				{
					return;
				}
				String destination = resolver.verifyDestination(url);
				SwingUtilities.invokeLater(() ->
				{
					if (current(authority))
					{
						message.accept(authority, browser.open(destination));
					}
				});
			}
			catch (IOException | RuntimeException failure)
			{
				if (current(authority))
				{
					message.accept(authority,
						failure.getMessage() + LINK + url + RETRY
							+ TrainingGuideResolver.FALLBACK);
				}
			}
		}))
		{
			message.accept(authority, QUEUE_BUSY);
		}
	}

	private boolean current(long authority)
	{
		return run.active() && authority == account.getAsLong();
	}

	public void source(String url)
	{
		if (run.active() && (GuideParser.safeWikiLink(url) != null || ApplicationLinks.CONTENT_LICENSE.equals(url)))
		{
			message.accept(-1L, browser.open(url));
		}
	}

	public void report()
	{
		if (run.active())
		{
			message.accept(-1L, browser.open(ApplicationLinks.ISSUES));
		}
	}

	/** Explicit clipboard gesture only; no destination request or browser action. */
	public boolean copyLink(String url)
	{
		return run.active() && url != null && (GuideParser.safeWikiLink(url) != null || TrainingGuideResolver.safe(url)
			|| ApplicationLinks.ISSUES.equals(url) || ApplicationLinks.CONTENT_LICENSE.equals(url))
			&& browser.copy(url);
	}
}

