package com.questcape.progress.capture;

import com.questcape.progress.activity.ActivityDetector;
import com.questcape.progress.activity.ActivityObservation;
import com.questcape.progress.activity.definitions.ActivityKey;
import com.questcape.progress.activity.detectors.BalloonUnlockDetector;
import com.questcape.progress.activity.detectors.DiaryTierDetector;
import com.questcape.progress.activity.detectors.HerbiFlaxHandInDetector;
import com.questcape.progress.activity.detectors.KnightWavesDetector;
import com.questcape.progress.activity.detectors.MuseumCampRewardDetector;
import com.questcape.progress.activity.detectors.NaturalHistoryQuizDetector;
import com.questcape.progress.activity.detectors.StrongholdCoinsDetector;
import com.questcape.progress.model.AccountProgress;
import com.questcape.progress.model.QuestKey;
import java.util.*;
import net.runelite.api.Client;

/** Explicit composition and duplicate validation, never discovery or last-writer-wins registration. */
@lombok.extern.slf4j.Slf4j
public final class ActivityRegistry
{
	public static final ActivityRegistry STANDARD = new ActivityRegistry(List.of(new DiaryTierDetector(),
		new BalloonUnlockDetector(), new StrongholdCoinsDetector(), new MuseumCampRewardDetector(),
		new HerbiFlaxHandInDetector(), new NaturalHistoryQuizDetector(), new KnightWavesDetector()));

	@lombok.Value
	private static class Registration
	{
		ActivityDetector detector;
		Set<ActivityKey> facts;
		Set<QuestKey> quests;
	}

	private final List<Registration> registrations;

	public ActivityRegistry(List<ActivityDetector> detectors)
	{
		List<Registration> definitions = new ArrayList<>();
		Set<ActivityKey> facts = new HashSet<>();
		Set<QuestKey> quests = new HashSet<>();
		for (ActivityDetector detector : detectors)
		{
			for (ActivityKey key : detector.facts())
			{
				if (!facts.add(key))
				{
					throw new IllegalArgumentException("Duplicate activity writer");
				}
			}
			for (QuestKey key : detector.quests())
			{
				if (!quests.add(key))
				{
					throw new IllegalArgumentException("Duplicate miniquest writer");
				}
			}
			definitions.add(new Registration(detector, Set.copyOf(detector.facts()), Set.copyOf(detector.quests())));
		}
		registrations = List.copyOf(definitions);
	}

	public ActivityObservation capture(Client client)
	{
		Map<ActivityKey, Boolean> facts = new HashMap<>();
		Map<QuestKey, AccountProgress.QuestStatus> quests = new HashMap<>();
		for (Registration registration : registrations)
		{
			ActivityObservation observation;
			try
			{
				observation = registration.getDetector().capture(client);
			}
			catch (RuntimeException failure)
			{
				log.debug("Activity family unavailable ({})", failure.getClass().getSimpleName());
				continue;
			}
			if (!registration.getFacts().containsAll(observation.getFacts().keySet())
				|| !registration.getQuests().containsAll(observation.getQuests().keySet()))
			{
				throw new IllegalStateException("Undeclared detector output");
			}
			facts.putAll(observation.getFacts());
			quests.putAll(observation.getQuests());
		}
		return new ActivityObservation(facts, quests);
	}
}

package com.questcape.progress.capture;

import com.questcape.progress.model.AccountProgress;
import java.util.*;
import javax.inject.*;
import net.runelite.api.*;
import net.runelite.client.config.*;

@Singleton
public class LiveProgressReader
{
	private final Client client;
	private final ConfigManager config;

	@Inject
	public LiveProgressReader(Client client, ConfigManager config)
	{
		this.client = client;
		this.config = config;
	}

	/** Only call on ClientThread after the login's first game tick. */
	public AccountProgress read()
	{
		if (client.getGameState() != GameState.LOGGED_IN || client.getLocalPlayer() == null
			|| config.getRSProfileKey() == null)
		{
			return null;
		}
		String name = client.getLocalPlayer().getName();
		if (name == null || name.isBlank() || client.getAccountHash() == -1L)
		{
			return null;
		}
		RuneScapeProfileType mode = RuneScapeProfileType.getCurrent(client);
		boolean established = config.getRSProfiles().stream().anyMatch(p -> p.getKey().equals(config.getRSProfileKey())
			&& p.getAccountHash() == client.getAccountHash() && p.getType() == mode);
		if (!established)
		{
			return null;
		}
		Map<String, AccountProgress.QuestStatus> quests = new HashMap<>();
		for (Quest quest : Quest.values())
		{
			QuestState state = quest.getState(client);
			quests.put(quest.name(), state == QuestState.FINISHED ? AccountProgress.QuestStatus.COMPLETE
				: state == QuestState.IN_PROGRESS ? AccountProgress.QuestStatus.IN_PROGRESS
					: AccountProgress.QuestStatus.INCOMPLETE);
		}
		Map<String, Integer> levels = new HashMap<>();
		for (Skill skill : Skill.values())
		{
			int level = client.getRealSkillLevel(skill);
			if (level > 0)
			{
				levels.put(skill.name(), level);
			}
		}
		com.questcape.progress.activity.ActivityObservation extra = com.questcape.progress.capture.ActivityRegistry.STANDARD
			.capture(client);
		extra.getQuests()
			.forEach((key, value) -> quests.put(com.questcape.persistence.LegacyKeyCodec.encode(key), value));
		Map<String, Boolean> facts = new HashMap<>();
		extra.getFacts()
			.forEach((key, value) -> facts.put(com.questcape.persistence.LegacyKeyCodec.encode(key), value));
		long now = System.currentTimeMillis();
		return new AccountProgress("live:" + config.getRSProfileKey() + ":" + mode.name(), name, mode.name(),
			"Live RuneLite",
			now, now, quests, levels, facts, Collections.emptySet());
	}
}

