package com.questcape.progress.evaluation;

import com.questcape.guide.model.GuideRow;
import com.questcape.progress.model.AccountProgress;
import lombok.Value;

@Value
public class Completion
{
	public enum State
	{
		COMPLETE("✓ Complete"), INCOMPLETE("○ Incomplete"), IN_PROGRESS("◐ In progress"), UNKNOWN("? Unknown"),
		INFORMATION("Information");

		private final String label;

		State(String label)
		{
			this.label = label;
		}

		public String label()
		{
			return label;
		}
	}

	State state;
	boolean manual;

	public String label()
	{
		return (state == State.UNKNOWN && manual ? "○ Not checked" : state.label()) + (manual ? " · manual" : "");
	}

	public static Completion of(GuideRow row, AccountProgress progress)
	{
		return of(row, progress, row.getKind() == GuideRow.Kind.TRAINING ? TrainingEvaluation.of(row, progress) : null);
	}

	public static Completion of(GuideRow row, AccountProgress progress, TrainingEvaluation training)
	{
		com.questcape.guide.model.ClassifiedAction action = row.action();
		if (action.getPolicy() == CompletionPolicy.INFORMATION)
		{
			return new Completion(State.INFORMATION, false);
		}
		if (progress == null)
		{
			return new Completion(State.UNKNOWN, false);
		}
		return new Completion(action.getPolicy().evaluate(action, progress, training, row.getKey()), action.manual());
	}
}

package com.questcape.progress.evaluation;

import com.questcape.guide.model.ClassifiedAction;
import com.questcape.progress.model.AccountProgress;

/** Closed domain policies own evaluation. Persisted key syntax and Swing do not belong here. */
public enum CompletionPolicy
{
	INFORMATION
	{
		public Completion.State evaluate(ClassifiedAction action, AccountProgress facts, TrainingEvaluation training,
			String key)
		{
			return Completion.State.INFORMATION;
		}
	},
	QUEST_START
	{
		public Completion.State evaluate(ClassifiedAction action, AccountProgress facts, TrainingEvaluation training,
			String key)
		{
			AccountProgress.QuestStatus value = facts.quest(action.getQuest());
			return value == AccountProgress.QuestStatus.IN_PROGRESS ? Completion.State.COMPLETE : questState(value);
		}
	},
	QUEST_FINISH
	{
		public Completion.State evaluate(ClassifiedAction action, AccountProgress facts, TrainingEvaluation training,
			String key)
		{
			return questState(facts.quest(action.getQuest()));
		}
	},
	TRAINING
	{
		public Completion.State evaluate(ClassifiedAction action, AccountProgress facts, TrainingEvaluation training,
			String key)
		{
			return training.getState();
		}
	},
	ACTIVITY
	{
		public Completion.State evaluate(ClassifiedAction action, AccountProgress facts, TrainingEvaluation training,
			String key)
		{
			Boolean value = facts.fact(action.getActivity());
			return value == null ? Completion.State.UNKNOWN
				: value ? Completion.State.COMPLETE : Completion.State.INCOMPLETE;
		}
	},
	MANUAL_KUDOS
	{
		public Completion.State evaluate(ClassifiedAction action, AccountProgress facts, TrainingEvaluation training,
			String key)
		{
			return facts.getManual().contains(key) ? Completion.State.COMPLETE : Completion.State.UNKNOWN;
		}
	},
	UNKNOWN
	{
		public Completion.State evaluate(ClassifiedAction action, AccountProgress facts, TrainingEvaluation training,
			String key)
		{
			return Completion.State.UNKNOWN;
		}
	};

	public abstract Completion.State evaluate(ClassifiedAction action, AccountProgress facts,
		TrainingEvaluation training, String manualKey);

	private static Completion.State questState(AccountProgress.QuestStatus status)
	{
		if (status == null)
		{
			return Completion.State.UNKNOWN;
		}
		switch (status)
		{
		case COMPLETE:
			return Completion.State.COMPLETE;
		case IN_PROGRESS:
			return Completion.State.IN_PROGRESS;
		case INCOMPLETE:
			return Completion.State.INCOMPLETE;
		default:
			throw new IllegalArgumentException("Unmapped quest state");
		}
	}
}

package com.questcape.progress.evaluation;

import com.questcape.guide.interpretation.SkillCatalog;
import com.questcape.guide.interpretation.SkillTargetKey;
import com.questcape.guide.interpretation.TrainingInstruction;
import com.questcape.guide.model.GuideRow;
import com.questcape.progress.model.AccountProgress;
import java.util.*;
import lombok.Value;
import net.runelite.api.Experience;

/** Shared domain result for cards, filters, totals, navigation and per-skill presentation. */
@Value
public class TrainingEvaluation
{
	private static final int PERCENT = 100;
	private static final List<net.runelite.api.Skill> COMBAT_SKILLS = List.of(net.runelite.api.Skill.ATTACK,
		net.runelite.api.Skill.STRENGTH, net.runelite.api.Skill.DEFENCE, net.runelite.api.Skill.HITPOINTS,
		net.runelite.api.Skill.MAGIC, net.runelite.api.Skill.RANGED, net.runelite.api.Skill.PRAYER);
	Completion.State state;
	List<Comparison> comparisons;
	boolean partial;

	@Value
	public static class Comparison
	{
		String skill;
		Integer level;
		Integer percent;
		boolean complete;
	}

	public static TrainingEvaluation of(GuideRow row, AccountProgress account)
	{
		TrainingInstruction instruction = row.training();
		boolean missing = instruction.isUnresolved(), complete = false, incomplete = false, inProgress = false;
		List<Comparison> comparisons = new ArrayList<>();
		for (TrainingInstruction.Target target : instruction.getTargets())
		{
			Integer level = level(account, target.key());
			Integer percent = null;
			if (level == null || !SkillCatalog.validLevel(target.getSkill(), target.getGoal()))
			{
				missing = true;
			}
			else
			{
				complete |= level >= target.getGoal();
				incomplete |= level < target.getGoal();
				inProgress |= target.getBase() != null && level >= target.getBase() && level < target.getGoal();
				if (target.getBase() != null)
				{
					percent = (int)Math.floor(PERCENT * Math.max(0, Math.min(1,
						(double)(level - target.getBase()) / (target.getGoal() - target.getBase()))));
				}
			}
			comparisons.add(new Comparison(target.getSkill(), level, percent,
				level != null && SkillCatalog.validLevel(target.getSkill(), target.getGoal())
					&& level >= target.getGoal()));
		}
		Completion.State state = !missing && !incomplete ? Completion.State.COMPLETE
			: inProgress || complete && incomplete ? Completion.State.IN_PROGRESS
				: incomplete ? Completion.State.INCOMPLETE : Completion.State.UNKNOWN;
		return new TrainingEvaluation(state, Collections.unmodifiableList(comparisons), missing);
	}

	private static Integer level(AccountProgress account, SkillTargetKey target)
	{
		if (account == null || target == null)
		{
			return null;
		}
		if (!target.combat())
		{
			return account.realLevel(target.getSkill());
		}
		if (COMBAT_SKILLS.stream().anyMatch(skill -> account.realLevel(skill) == null))
		{
			return null;
		}
		return Experience.getCombatLevel(account.realLevel(net.runelite.api.Skill.ATTACK),
			account.realLevel(net.runelite.api.Skill.STRENGTH), account.realLevel(net.runelite.api.Skill.DEFENCE),
			account.realLevel(net.runelite.api.Skill.HITPOINTS), account.realLevel(net.runelite.api.Skill.MAGIC),
			account.realLevel(net.runelite.api.Skill.RANGED), account.realLevel(net.runelite.api.Skill.PRAYER));
	}
}

package com.questcape.progress.model;

import java.util.*;
