package com.questcape.ui.interaction;

import com.questcape.ui.GuideActions;
import com.questcape.ui.style.UiCopy;
import com.questcape.ui.style.UiMetrics;
import java.awt.*;
import java.awt.event.*;
import java.util.function.*;
