package com.questcape.ui.panel;

import com.questcape.guide.model.ClassifiedAction;
import com.questcape.guide.model.GuideRow;
import com.questcape.guide.model.GuideSnapshot;
import com.questcape.progress.evaluation.Completion;
import com.questcape.progress.evaluation.TrainingEvaluation;
import com.questcape.progress.model.AccountProgress;
import com.questcape.ui.style.UiCopy;
import java.util.*;
import lombok.Value;

/** One pure projection owns whole-route totals, filtered eligibility and card facts. */
@Value
final class GuideProjection
{
	@Value
	static class Entry
	{
		GuideRow row;
		Completion completion;
		TrainingEvaluation training;
		boolean visible;
		String explanation;
	}

	List<Entry> entries;
	int complete;
	int unknown;

	static GuideProjection of(GuideSnapshot guide, AccountProgress account, GuideRow.Kind type, Completion.State state)
	{
		List<Entry> entries = new ArrayList<>();
		int complete = 0, unknown = 0;
		for (GuideRow row : guide == null ? Collections.<GuideRow>emptyList() : guide.getRows())
		{
			if (!row.isActionable())
			{
				continue;
			}
			TrainingEvaluation training = row.getKind() == GuideRow.Kind.TRAINING ? TrainingEvaluation.of(row, account)
				: null;
			Completion completion = Completion.of(row, account, training);
			if (completion.getState() == Completion.State.COMPLETE)
			{
				complete++;
			}
			if (completion.getState() == Completion.State.UNKNOWN)
			{
				unknown++;
			}
			entries.add(new Entry(row, completion, training,
				(type == null || type == row.getKind()) && (state == null || state == completion.getState()),
				explanation(row, account, completion, training)));
		}
		return new GuideProjection(Collections.unmodifiableList(entries), complete, unknown);
	}

	private static String explanation(GuideRow row, AccountProgress account, Completion completion,
		TrainingEvaluation training)
	{
		if (account == null)
		{
			return UiCopy.MISSING_ACCOUNT;
		}
		if (row.action().getReason() == ClassifiedAction.Reason.CONFLICTING_IDENTITY)
		{
			return UiCopy.AMBIGUOUS_ACTION;
		}
		if (training != null && training.isPartial())
		{
			return row.training().isUnresolved() ? UiCopy.UNSUPPORTED_TRAINING : UiCopy.MISSING_SKILL;
		}
		if (completion.getState() != Completion.State.UNKNOWN)
		{
			return "";
		}
		if (row.isManual())
		{
			return UiCopy.MANUAL_UNCHECKED;
		}
		return row.getQuestIdentity() != null || row.getActivityIdentity() != null ? UiCopy.MISSING_OBSERVATION
			: UiCopy.UNSUPPORTED_ACTION;
	}
}

package com.questcape.ui.panel;

import com.questcape.guide.model.GuideRow;
import com.questcape.guide.model.GuideSnapshot;
import com.questcape.integration.links.ApplicationLinks;
import com.questcape.integration.links.TrainingGuideResolver;
import com.questcape.ui.GuideActions;
import com.questcape.ui.interaction.LinkCopyGesture;
import java.awt.*;
import java.util.*;
import java.util.List;
import java.util.function.BiConsumer;
import javax.swing.*;
import javax.swing.border.*;

import static com.questcape.ui.style.UiComponents.*;
import static com.questcape.ui.style.UiTheme.*;

/** Source-order cards, expansion keys, notes and attribution belong to the route view. */
final class GuideRouteView extends JScrollPane
{
	final JPanel body = new WidthTrackingPanel(), rowsPanel = vertical();
	final List<GuideRowCard> rows = new ArrayList<>();
	final List<Component> notes = new ArrayList<>();
	private final Set<String> expanded = new HashSet<>();
	private final GuideAssets assets;
	private final GuideActions actions;
	private final TrainingGuideResolver training;
	private GuideSnapshot guide;

	GuideRouteView(GuideActions actions, GuideAssets assets, TrainingGuideResolver training, JTextArea provenance)
	{
		this.actions = actions;
		this.assets = assets;
		this.training = training;
		setViewportView(body);
		body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
		body.setBackground(BACKGROUND);
		body.setBorder(new EmptyBorder(0, 10, 8, 10));
		body.add(rowsPanel);
		JPanel footer = vertical();
		footer.setBorder(new EmptyBorder(10, 0, 8, 0));
		provenance.setVisible(false);
		JButton provenanceToggle = textButton("Source and progress details ▾");
		provenanceToggle.addActionListener(e ->
		{
			provenance.setVisible(!provenance.isVisible());
			provenanceToggle
				.setText(provenance.isVisible() ? "Source and progress details ▴" : "Source and progress details ▾");
			body.revalidate();
		});
		footer.add(provenanceToggle);
		footer.add(provenance);
		JButton source = textButton("OSRS Wiki ↗");
		java.util.function.Supplier<String> sourceUrl = () -> guide == null || guide.getRevision() == null
			? GuideSnapshot.SOURCE
			: GuideSnapshot.SOURCE + "?oldid=" + guide.getRevision();
		source.addActionListener(e -> actions.source(sourceUrl.get()));
		LinkCopyGesture.install(source, sourceUrl, actions);
		footer.add(source);
		footer.add(text("OSRS Wiki contributors\nCC BY-NC-SA 3.0 · Additional terms apply", MUTED, 13, false));
		JButton license = textButton("Content license ↗");
		license.addActionListener(e -> actions.source(ApplicationLinks.CONTENT_LICENSE));
		LinkCopyGesture.install(license, () -> ApplicationLinks.CONTENT_LICENSE, actions);
		footer.add(license);
		body.add(footer);

	}

	void replace(GuideSnapshot snapshot, BiConsumer<GuideRow, Boolean> disclosed, Runnable userIntent)
	{
		guide = snapshot;
		rows.forEach(GuideRowCard::dispose);
		rows.clear();
		notes.clear();
		assets.clearBindings();
		rowsPanel.removeAll();
		if (snapshot != null)
		{
			int number = 0;
			for (GuideRow row : snapshot.getRows())
			{
				if (!row.isActionable())
				{
					Component note = comment(row), spacer = Box.createVerticalStrut(9);
					notes.add(note);
					notes.add(spacer);
					rowsPanel.add(note);
					rowsPanel.add(spacer);
					continue;
				}
				GuideRowCard card = new GuideRowCard(row, ++number, expanded.contains(row.getKey()), assets, actions,
					training,
					(changed, open) ->
					{
						if (open)
						{
							expanded.add(changed.getKey());
						}
						else
						{
							expanded.remove(changed.getKey());
						}
						disclosed.accept(changed, open);
					}, userIntent);
				rows.add(card);
				rowsPanel.add(card);
				rowsPanel.add(card.spacer);
			}
		}
		body.revalidate();
	}

	private static JPanel comment(GuideRow row)
	{
		JPanel comment = vertical();
		comment.setBorder(new CompoundBorder(new MatteBorder(1, 0, 1, 0, BORDER), new EmptyBorder(12, 2, 12, 2)));
		comment.add(text(row.getTitle(), MUTED, 14, false));
		comment.getAccessibleContext().setAccessibleName("Guide note: " + row.getTitle());
		return comment;
	}

	private static final class WidthTrackingPanel extends JPanel implements Scrollable
	{
		public Dimension getPreferredScrollableViewportSize()
		{
			return new Dimension(225, 600);
		}

		public int getScrollableUnitIncrement(Rectangle r, int orientation, int direction)
		{
			return 24;
		}

		public int getScrollableBlockIncrement(Rectangle r, int orientation, int direction)
		{
			return Math.max(24, r.height - 40);
		}

		public boolean getScrollableTracksViewportWidth()
		{
			return true;
		}

		public boolean getScrollableTracksViewportHeight()
		{
			return false;
		}
	}

}

