package com.questcape.ui.panel;

import com.questcape.ui.panel.GuideNavigator.ScrollAnchor;
import com.questcape.ui.style.UiCopy;
import com.questcape.ui.style.UiMetrics;
import java.awt.*;
import java.util.*;
import java.util.List;
import java.util.function.Consumer;
import javax.swing.*;
import javax.swing.event.*;

import static com.questcape.ui.style.UiComponents.requireEdt;

/** Debounced local find/traversal, saved origin and wrap belong to one EDT owner. */
final class GuideSearchController
{
	final JTextField search;
	final JButton searchMatches, clearSearch;
	final List<GuideRowCard> rows, matches = new ArrayList<>();
	final GuideNavigator navigator;
	final Runnable applyFilters;
	final Consumer<String> feedback;
	final javax.swing.Timer searchTimer = new javax.swing.Timer(UiMetrics.DEBOUNCE_MS, e -> searchNow());
	int matchIndex = -1;
	String matchedQuery = "";
	ScrollAnchor searchOrigin;
	long wrapArmedAt, searchIntent;
	boolean resetting, disposed;

	GuideSearchController(GuideSearchBar bar, List<GuideRowCard> rows, GuideNavigator navigator, Runnable applyFilters,
		Consumer<String> feedback)
	{
		search = bar.search;
		searchMatches = bar.searchMatches;
		clearSearch = bar.clearSearch;
		this.rows = rows;
		this.navigator = navigator;
		this.applyFilters = applyFilters;
		this.feedback = feedback;
		searchTimer.setRepeats(false);
		search.addActionListener(e -> nextSearchMatch(System.nanoTime()));
		searchMatches.addActionListener(e -> nextSearchMatch(System.nanoTime()));
		search.getDocument().addDocumentListener(new DocumentListener()
		{
			public void insertUpdate(DocumentEvent e)
			{
				searchChanged();
			}

			public void removeUpdate(DocumentEvent e)
			{
				searchChanged();
			}

			public void changedUpdate(DocumentEvent e)
			{
				searchChanged();
			}
		});
	}

	void visibilityChanged(boolean changed)
	{
		if (!searchTimer.isRunning() && !matchedQuery.isEmpty())
		{
			if (changed)
			{
				refreshMatches(true);
			}
			else
			{
				updateMatchStatus();
			}
		}
		else
		{
			feedback.accept("");
		}
	}

	void dispose()
	{
		disposed = true;
		searchTimer.stop();
		clearMatches();
		searchOrigin = null;
	}

	private void applyFilters()
	{
		applyFilters.run();
	}

	void searchChanged()
	{
		searchTimer.stop();
		clearSearch.setEnabled(!search.getText().isBlank());
		if (resetting || disposed)
		{
			return;
		}
		String query = StepSearch.normalize(search.getText());
		if (!query.isEmpty() && searchOrigin == null)
		{
			searchOrigin = navigator.captureAnchor();
		}
		searchIntent = ++navigator.scrollIntent;
		clearMatches();
		feedback.accept("");
		if (!query.isEmpty())
		{
			searchMatches.setText("…");
			searchMatches.setVisible(true);
			searchMatches.setEnabled(false);
			searchTimer.restart();
		}
		else
		{
			restoreSearchOrigin();
		}
	}

	void filtersChanged()
	{
		searchTimer.stop();
		wrapArmedAt = 0;
		if (StepSearch.normalize(search.getText()).isEmpty())
		{
			searchOrigin = null;
		}
		navigator.scrollIntent++;
		applyFilters();
		long intent = navigator.scrollIntent;
		SwingUtilities.invokeLater(() ->
		{
			if (disposed || intent != navigator.scrollIntent)
			{
				return;
			}
			navigator.body.validate();
			if (StepSearch.normalize(search.getText()).isEmpty())
			{
				navigator.jumpTo(0);
			}
			else
			{
				searchIntent = navigator.scrollIntent;
				searchNow();
			}
		});
	}

	void searchNow()
	{
		requireEdt();
		searchTimer.stop();
		if (disposed || searchIntent != navigator.scrollIntent || StepSearch.normalize(search.getText()).isEmpty())
		{
			return;
		}
		int best = refreshMatches(false);
		if (!matches.isEmpty())
		{
			showMatch(best);
		}
	}

	int refreshMatches(boolean preserveCurrent)
	{
		String key = preserveCurrent && matchIndex >= 0 && matchIndex < matches.size()
			? matches.get(matchIndex).row.getKey()
			: null;
		matches.clear();
		matchedQuery = StepSearch.normalize(search.getText());
		GuideRowCard best = null;
		int bestScore = Integer.MAX_VALUE;
		for (GuideRowCard card : rows)
		{
			if (!card.isVisible())
			{
				continue;
			}
			int candidate = StepSearch.score(card.row.getTitle(), search.getText());
			if (candidate < Integer.MAX_VALUE)
			{
				matches.add(card);
				if (candidate < bestScore)
				{
					best = card;
					bestScore = candidate;
				}
			}
		}
		matches.sort(Comparator.comparingInt(card -> card.stepNumber));
		matchIndex = -1;
		for (int i = 0; i < matches.size(); i++)
		{
			if (matches.get(i).row.getKey().equals(key))
			{
				matchIndex = i;
				break;
			}
		}
		wrapArmedAt = 0;
		updateMatchStatus();
		return matches.indexOf(best);
	}

	void showMatch(int index)
	{
		matchIndex = index;
		wrapArmedAt = 0;
		GuideRowCard card = matches.get(index);
		updateMatchStatus();
		navigator.jumpTo(navigator.position(card));
	}

	void nextSearchMatch(long now)
	{
		requireEdt();
		if (disposed || StepSearch.normalize(search.getText()).isEmpty())
		{
			return;
		}
		if (searchTimer.isRunning() || !matchedQuery.equals(StepSearch.normalize(search.getText())))
		{
			searchIntent = navigator.scrollIntent;
			searchNow();
			return;
		}
		if (matches.isEmpty())
		{
			return;
		}
		if (matchIndex < matches.size() - 1)
		{
			showMatch(matchIndex + 1);
		}
		else if (matches.size() > 1)
		{
			if (wrapArmedAt != 0 && now - wrapArmedAt >= 0 && now - wrapArmedAt <= UiMetrics.WRAP_NANOS)
			{
				showMatch(0);
			}
			else
			{
				wrapArmedAt = now;
				feedback.accept(" · Press Enter twice to return to the first match");
			}
		}
	}

	void updateMatchStatus()
	{
		searchMatches.setVisible(!matchedQuery.isEmpty());
		searchMatches.setText((matchIndex + 1) + "/" + matches.size());
		searchMatches.setEnabled(!matches.isEmpty());
		searchMatches.getAccessibleContext()
			.setAccessibleName("Search match " + (matchIndex + 1) + " of " + matches.size());
		searchMatches.setToolTipText("Next match (Enter). At the last match, press Enter twice within 500 ms to wrap.");
		feedback.accept(matches.isEmpty() ? " · " + UiCopy.NO_MATCH
			: matchIndex >= 0 ? " · Search match: step " + matches.get(matchIndex).stepNumber : "");
	}

	void clearMatches()
	{
		matches.clear();
		matchedQuery = "";
		matchIndex = -1;
		wrapArmedAt = 0;
		searchMatches.setVisible(false);
	}

	void restoreSearchOrigin()
	{
		ScrollAnchor origin = searchOrigin;
		if (origin != null)
		{
			navigator.restoreAfterLayout(
				new ScrollAnchor(origin.key, origin.offset, origin.absolute, navigator.scrollIntent),
				() -> searchOrigin = null);
		}
	}

	void userNavigated()
	{
		wrapArmedAt = 0;
		if (StepSearch.normalize(search.getText()).isEmpty())
		{
			searchOrigin = null;
		}
		if (searchTimer.isRunning())
		{
			searchTimer.stop();
			refreshMatches(false);
		}
	}

	void reset(Runnable clearSelections)
	{
		resetting = true;
		searchTimer.stop();
		clearSelections.run();
		search.setText("");
		clearMatches();
		resetting = false;
		navigator.scrollIntent++;
		applyFilters();
		if (searchOrigin != null)
		{
			restoreSearchOrigin();
		}
		else
		{
			navigator.jumpTo(0);
		}
	}
}

package com.questcape.ui.panel;

import com.questcape.guide.interpretation.TrainingInstruction;
import java.awt.*;
import java.util.*;
import javax.swing.*;
import javax.swing.text.*;
import net.runelite.api.Skill;

/** Inert styled text: skill icons come only from RuneLite, never the guide's image URLs. */
final class SkillText extends JTextPane
{
	private static final Icon PENDING_ICON = new Icon()
	{
		public int getIconWidth() { return 16; }
		public int getIconHeight() { return 16; }
		public void paintIcon(Component c, Graphics g, int x, int y) { }
	};

	private final Map<Integer, Skill> icons = new LinkedHashMap<>();

	SkillText(String source, Font font, Color color, Map<Skill, Icon> images,
		java.util.List<TrainingInstruction.Token> tokens)
	{
		setFont(font);
		setForeground(color);
		setOpaque(false);
		setEditable(false);
		setAlignmentX(LEFT_ALIGNMENT);
		setBorder(BorderFactory.createEmptyBorder(2, 0, 2, 0));
		((DefaultCaret)getCaret()).setUpdatePolicy(DefaultCaret.NEVER_UPDATE);
		getAccessibleContext().setAccessibleName(source);
		StringBuilder text = new StringBuilder();
		int end = 0;
		for (TrainingInstruction.Token token : tokens)
		{
			String identity = token.getSkill();
			text.append(source, end, token.getStart());
			if (identity != null)
			{
				icons.put(text.length(), Skill.valueOf(identity));
				text.append('\ufffc').append(' ');
			}
			text.append(source, token.getStart(), token.getEnd());
			end = token.getEnd();
		}
		text.append(source.substring(end));
		setText(text.toString());
		updateIcons(images);
	}

	void updateIcons(Map<Skill, Icon> images)
	{
		icons.forEach((offset, skill) ->
		{
			SimpleAttributeSet attributes = new SimpleAttributeSet();
			StyleConstants.setIcon(attributes, images.getOrDefault(skill, PENDING_ICON));
			getStyledDocument().setCharacterAttributes(offset, 1, attributes, true);
		});
	}

	@Override
	public Dimension getPreferredSize()
	{
		int width = getWidth() > 0 ? getWidth() : 180;
		Insets insets = getInsets();
		View root = getUI().getRootView(this);
		root.setSize(Math.max(1, width - insets.left - insets.right), Integer.MAX_VALUE);
		return new Dimension(width, (int)Math.ceil(root.getPreferredSpan(View.Y_AXIS)) + insets.top + insets.bottom);
	}

	@Override
	public Dimension getMinimumSize()
	{
		return new Dimension(10, getPreferredSize().height);
	}

	@Override
	public Dimension getMaximumSize()
	{
		return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
	}
}

package com.questcape.ui.panel;

import java.util.Locale;

/** Bounded title matching, with route order used to break equal scores. */
final class StepSearch
{
	private StepSearch()
	{
	}

	static String normalize(String value)
	{
		return value.toLowerCase(Locale.ROOT).replaceAll("[^\\p{L}\\p{N}]+", " ").trim();
	}

	static int score(String title, String query)
	{
		String name = normalize(title), needle = normalize(query);
		if (needle.isEmpty() || needle.length() > 160)
		{
			return Integer.MAX_VALUE;
		}
		if (name.equals(needle))
		{
			return 0;
		}
		if (name.startsWith(needle))
		{
			return 10;
		}
		if (name.contains(needle))
		{
			return 20;
		}
		boolean tokens = true;
		for (String word : needle.split(" "))
		{
			tokens &= name.contains(word);
		}
		if (tokens)
		{
			return 30;
		}
		if (needle.length() < 3)
		{
			return Integer.MAX_VALUE;
		}
		int distance = distance(name, needle);
		for (String word : name.split(" "))
		{
			distance = Math.min(distance, distance(word, needle));
		}
		return distance <= Math.max(1, needle.length() / 4) ? 40 + distance : Integer.MAX_VALUE;
	}

	private static int distance(String a, String b)
	{
		if (Math.abs(a.length() - b.length()) > Math.max(1, b.length() / 4))
		{
			return Integer.MAX_VALUE;
		}
		int[] previous = new int[b.length() + 1];
		for (int j = 0; j <= b.length(); j++)
		{
			previous[j] = j;
		}
		for (int i = 1; i <= a.length(); i++)
		{
			int[] current = new int[b.length() + 1];
			current[0] = i;
			for (int j = 1; j <= b.length(); j++)
			{
				current[j] = Math.min(Math.min(current[j - 1] + 1, previous[j] + 1),
					previous[j - 1] + (a.charAt(i - 1) == b.charAt(j - 1) ? 0 : 1));
			}
			previous = current;
		}
		return previous[b.length()];
	}
}

package com.questcape.ui.panel;

import com.questcape.guide.interpretation.TrainingInstruction;
import com.questcape.progress.evaluation.TrainingEvaluation;
import com.questcape.ui.style.UiCopy;
import com.questcape.ui.style.UiMetrics;
import java.awt.*;
import java.awt.geom.*;
import java.util.Objects;
import javax.accessibility.*;
import javax.swing.*;

import static com.questcape.ui.style.UiComponents.*;
import static com.questcape.ui.style.UiTheme.*;

/** Compact presentation of prepared real-level comparisons; never calculates completion. */
final class TrainingProgress extends JPanel
{
	private TrainingEvaluation previous;
	private boolean supported;
	private final java.util.List<Circle> circles = new java.util.ArrayList<>();

	TrainingProgress(TrainingInstruction instruction)
	{
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setOpaque(false);
		setAlignmentX(LEFT_ALIGNMENT);
		if (instruction.getTargets().isEmpty())
		{
			Circle circle = new Circle();
			circles.add(circle);
			add(circle);
		}
		for (TrainingInstruction.Target target : instruction.getTargets())
		{
			Circle circle = new Circle();
			circles.add(circle);
			String name = human(target.getSkill());
			circle.getAccessibleContext().setAccessibleName(name);
			if (instruction.getTargets().size() > 1)
			{
				JPanel line = new JPanel(new FlowLayout(FlowLayout.LEFT, UiMetrics.PROGRESS_GAP, 0));
				line.setAlignmentX(LEFT_ALIGNMENT);
				line.setOpaque(false);
				line.add(circle);
				JLabel skill = new JLabel(name);
				skill.setFont(font(UiMetrics.META, false));
				skill.setForeground(MUTED);
				line.add(skill);
				add(line);
			}
			else
			{
				add(circle);
			}
		}
	}

	void update(TrainingEvaluation result, boolean supported)
	{
		if (Objects.equals(previous, result) && this.supported == supported)
		{
			return;
		}
		previous = result;
		this.supported = supported;
		for (int index = 0; index < circles.size(); index++)
		{
			if (result == null || index >= result.getComparisons().size())
			{
				circles.get(index).update(null, false);
			}
			else
			{
				TrainingEvaluation.Comparison comparison = result.getComparisons().get(index);
				circles.get(index).update(supported ? comparison.getPercent() : null,
					supported && comparison.isComplete());
			}
		}
		repaint();
	}

	static final class Circle extends JComponent
	{
		Integer percent;
		boolean complete;

		Circle()
		{
			Dimension size = new Dimension(UiMetrics.TRAINING_CIRCLE, UiMetrics.TRAINING_CIRCLE);
			setPreferredSize(size);
			setMinimumSize(size);
			setMaximumSize(size);
			setAlignmentX(LEFT_ALIGNMENT);
			setFont(font(UiMetrics.META, true));
			update(null, false);
		}

		void update(Integer percent, boolean complete)
		{
			this.percent = complete ? Integer.valueOf(UiMetrics.FULL_PERCENT) : percent;
			this.complete = complete;
			setToolTipText(this.percent == null ? UiCopy.UNDEFINED : this.percent + "%");
			getAccessibleContext()
				.setAccessibleDescription((complete ? UiCopy.TRAINING_COMPLETE : UiCopy.TRAINING_PROGRESS) + ". "
					+ getToolTipText() + ". " + UiCopy.INTERVAL_TOOLTIP);
		}

		@Override
		protected void paintComponent(Graphics original)
		{
			Graphics2D g = (Graphics2D)original.create();
			try
			{
				g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
				g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
				double size = Math.min(getWidth(), getHeight()) - UiMetrics.CIRCLE_INSET * 2;
				double x = (getWidth() - size) / 2, y = (getHeight() - size) / 2;
				g.setStroke(new BasicStroke(UiMetrics.CIRCLE_STROKE, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
				g.setColor(BORDER);
				g.draw(new Ellipse2D.Double(x, y, size, size));
				g.setColor(complete ? GREEN : percent != null && percent > 0 ? GOLD : MUTED);
				if (percent != null && percent > 0)
				{
					g.draw(
						new Arc2D.Double(x, y, size, size, UiMetrics.CIRCLE_START_DEGREES,
							(double)UiMetrics.FULL_CIRCLE_DEGREES * percent / UiMetrics.FULL_PERCENT, Arc2D.OPEN));
				}
				if (complete)
				{
					Path2D check = new Path2D.Double();
					check.moveTo(x + size * .28, y + size * .52);
					check.lineTo(x + size * .44, y + size * .67);
					check.lineTo(x + size * .73, y + size * .34);
					g.draw(check);
				}
				else
				{
					String number = percent == null ? UiCopy.UNDEFINED : percent.toString();
					g.setColor(TEXT);
					g.setFont(getFont());
					FontMetrics metrics = g.getFontMetrics();
					g.drawString(number, (getWidth() - metrics.stringWidth(number)) / 2,
						(getHeight() - metrics.getHeight()) / 2 + metrics.getAscent());
				}
			}
			finally
			{
				g.dispose();
			}
		}

		@Override
		public AccessibleContext getAccessibleContext()
		{
			if (accessibleContext == null)
			{
				accessibleContext = new AccessibleCircle();
			}
			return accessibleContext;
		}

		private final class AccessibleCircle extends AccessibleJComponent implements AccessibleValue
		{
			@Override
			public AccessibleRole getAccessibleRole()
			{
				return AccessibleRole.PROGRESS_BAR;
			}

			@Override
			public AccessibleValue getAccessibleValue()
			{
