package com.questcape.ui.style;

import com.questcape.guide.model.GuideRow;
import java.awt.*;
import java.awt.geom.Path2D;
import javax.swing.Icon;

/** Small vector fallbacks until RuneLite's standard quest, diary and skills sprites are available. */
public final class StepIcons implements Icon
{
	private final GuideRow.Kind kind;
	private final Icon questIcon;

	public StepIcons(GuideRow.Kind kind)
	{
		this(kind, null);
	}

	public StepIcons(GuideRow.Kind kind, Icon questIcon)
	{
		this.kind = kind;
		this.questIcon = questIcon;
	}

	@Override
	public int getIconWidth()
	{
		return 16;
	}

	@Override
	public int getIconHeight()
	{
		return 16;
	}

	@Override
	public void paintIcon(Component component, Graphics graphics, int x, int y)
	{
		Graphics2D g = (Graphics2D)graphics.create();
		try
		{
			g.translate(x, y);
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setStroke(new BasicStroke(1.5f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g.setColor(UiTheme.kindColor(kind));
			switch (kind)
			{
			case QUEST:
			case MINIQUEST:
			case DIARY:
				if (questIcon != null)
				{
					questIcon.paintIcon(component, g, 0, 0);
				}
				else
				{
					g.setColor(kind == GuideRow.Kind.DIARY ? UiTheme.GREEN : UiTheme.BLUE);
					Path2D star = new Path2D.Double();
					star.moveTo(8, 1);
					star.lineTo(10, 6);
					star.lineTo(15, 8);
					star.lineTo(10, 10);
					star.lineTo(8, 15);
					star.lineTo(6, 10);
					star.lineTo(1, 8);
					star.lineTo(6, 6);
					star.closePath();
					g.fill(star);
					g.setColor(UiTheme.TEXT);
					g.drawLine(8, 4, 8, 11);
				}
				if (kind == GuideRow.Kind.MINIQUEST)
				{
					g.setColor(UiTheme.CARD);
					g.fillOval(9, 9, 7, 7);
					g.setColor(UiTheme.GOLD);
					g.fillOval(10, 10, 5, 5);
				}
				break;
			case TRAINING:
				g.fillRect(1, 10, 3, 5);
				g.fillRect(6, 6, 3, 9);
				g.fillRect(11, 1, 3, 14);
				break;
			case UNLOCK:
				g.drawArc(4, 1, 8, 10, 0, 180);
				g.fillRoundRect(2, 6, 12, 9, 3, 3);
				g.setColor(UiTheme.CARD);
				g.drawLine(8, 9, 8, 12);
				break;
			case ACTIVITY:
				g.drawRoundRect(2, 2, 12, 13, 2, 2);
				g.fillRoundRect(5, 0, 6, 4, 2, 2);
				g.drawLine(5, 9, 7, 11);
				g.drawLine(7, 11, 11, 6);
				break;
			default:
				g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 16));
				g.drawString("?", 4, 14);
			}
		}
		finally
		{
			g.dispose();
		}
	}
}

package com.questcape.ui.style;

import java.awt.*;
import javax.swing.*;
import javax.swing.border.*;
import javax.swing.plaf.basic.BasicHTML;
import javax.swing.text.*;
import net.runelite.client.ui.FontManager;

import static com.questcape.ui.style.UiTheme.*;
import static java.awt.Component.LEFT_ALIGNMENT;

/** Shared native metrics and inert wrapped text/button presentation. */
public final class UiComponents
{
	private UiComponents()
	{
	}

	public static void requireEdt()
	{
		if (!SwingUtilities.isEventDispatchThread())
		{
			throw new IllegalStateException("UI updates must run on EDT");
		}
	}

	public static void setText(JTextArea area, String value)
	{
		String safe = value == null ? "" : value;
		if (!area.getText().equals(safe))
		{
			area.setText(safe);
		}
	}

	public static String human(String value)
	{
		String text = value.toLowerCase(java.util.Locale.ROOT).replace('_', ' ');
		return text.isEmpty() ? text : Character.toUpperCase(text.charAt(0)) + text.substring(1);
	}

	public static void quietFocus(JButton button, int padding)
	{
		quietFocus(button, padding, padding);
	}

	public static void quietFocus(JButton button, int vertical, int horizontal)
	{
		focusBorder(button, vertical, horizontal, QUIET_BORDER);
	}

	public static void focusBorder(JButton button, int vertical, int horizontal, Color normal)
	{
		Runnable border = () -> button
			.setBorder(new CompoundBorder(new LineBorder(button.isFocusOwner() ? BLUE : normal),
				new EmptyBorder(vertical, horizontal, vertical, horizontal)));
		border.run();
		button.addFocusListener(new java.awt.event.FocusAdapter()
		{
			public void focusGained(java.awt.event.FocusEvent e)
			{
				border.run();
			}

			public void focusLost(java.awt.event.FocusEvent e)
			{
				border.run();
			}
		});
	}

	public static JPanel vertical()
	{
		JPanel p = new JPanel();
		p.setOpaque(false);
		p.setLayout(new BoxLayout(p, BoxLayout.Y_AXIS));
		p.setAlignmentX(LEFT_ALIGNMENT);
		return p;
	}

	public static JTextArea text(String value, Color color, int size, boolean bold)
	{
		JTextArea text = new WrappedText(value);
		text.setFont(font(size, bold));
		text.setForeground(color);
		text.setLineWrap(true);
		text.setWrapStyleWord(true);
		text.setEditable(false);
		text.setOpaque(false);
		text.setAlignmentX(LEFT_ALIGNMENT);
		text.setBorder(new EmptyBorder(2, 0, 2, 0));
		((DefaultCaret)text.getCaret()).setUpdatePolicy(DefaultCaret.NEVER_UPDATE);
		return text;
	}

	public static Font font(int size, boolean bold)
	{
		return FontManager.getFallbackFont("Segoe UI", bold ? Font.BOLD : Font.PLAIN, size);
	}

	private static final class WrappedText extends JTextArea
	{
		WrappedText(String value)
		{
			super(value);
		}

		@Override
		protected void paintComponent(Graphics graphics)
		{
			Graphics2D smooth = (Graphics2D)graphics.create();
			try
			{
				smooth.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
				super.paintComponent(smooth);
			}
			finally
			{
				smooth.dispose();
			}
		}

		@Override
		public Dimension getPreferredSize()
		{
			// Let the installed UI measure its editor view; sizing the root directly undercounts
			// wrapped lines with RuneLite's FlatLaf text UI and clips the end of long titles.
			Dimension preferred = super.getPreferredSize();
			return new Dimension(getWidth() > 0 ? getWidth() : 180, preferred.height);
		}

		@Override
		public Dimension getMinimumSize()
		{
			return new Dimension(10, getPreferredSize().height);
		}

		@Override
		public Dimension getMaximumSize()
		{
			return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
		}

		@Override
		public JToolTip createToolTip()
		{
			JToolTip tooltip = super.createToolTip();
			tooltip.setFont(font(14, false));
			return tooltip;
		}
	}

	public static JButton button(String label)
	{
		JButton b = new WrappedButton(label);
		b.setFont(font(14, true));
		b.setForeground(TEXT);
		b.setBackground(CARD);
		b.setBorder(new CompoundBorder(new LineBorder(BORDER), new EmptyBorder(7, 6, 7, 6)));
		b.setFocusPainted(true);
		b.setAlignmentX(LEFT_ALIGNMENT);
		b.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		return b;
	}

	/** Let HTML titles use the actual sidebar width instead of a fixed CSS width. */
	private static final class WrappedButton extends JButton
	{
		WrappedButton(String label)
		{
			super(label);
		}

		@Override
		public Dimension getPreferredSize()
		{
			View html = (View)getClientProperty(BasicHTML.propertyKey);
			if (html == null)
			{
				return super.getPreferredSize();
			}
			Container parent = getParent();
			int width = parent == null || parent.getWidth() <= 0 ? 180
				: parent.getWidth() - parent.getInsets().left - parent.getInsets().right;
			Insets insets = getInsets();
			html.setSize(Math.max(1, width - insets.left - insets.right), 0);
			return new Dimension(width,
				(int)Math.ceil(html.getPreferredSpan(View.Y_AXIS)) + insets.top + insets.bottom);
		}

		@Override
		public Dimension getMaximumSize()
		{
			return getClientProperty(BasicHTML.propertyKey) == null ? super.getMaximumSize()
				: new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
		}

		@Override
		public Dimension getMinimumSize()
		{
			return getClientProperty(BasicHTML.propertyKey) == null ? super.getMinimumSize()
				: new Dimension(10, getPreferredSize().height);
		}

		@Override
		public JToolTip createToolTip()
		{
			JToolTip tooltip = super.createToolTip();
			tooltip.setFont(font(14, false));
			return tooltip;
		}
	}

	public static JButton textButton(String label)
	{
		JButton b = button(label);
		b.setContentAreaFilled(false);
		b.setBorder(new EmptyBorder(5, 0, 5, 0));
		b.setForeground(BLUE);
		return b;
	}

	public static JButton iconButton(String label, Icon icon)
	{
		JButton b = button("");
		b.setIcon(icon);
		b.setToolTipText(label);
		b.getAccessibleContext().setAccessibleName(label);
		b.setPreferredSize(new Dimension(34, 34));
		b.setBorder(new EmptyBorder(7, 7, 7, 7));
		b.setContentAreaFilled(false);
		return b;
	}

	public static String escape(String value)
	{
		return value.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace("\"", "&quot;");
	}

}

