package com.questcape.guide.repository;

import com.google.gson.*;
import com.questcape.guide.model.GuideRow;
import com.questcape.guide.model.GuideSnapshot;
import com.questcape.guide.parsing.GuideParser;
import com.questcape.guide.parsing.GuideParserTest;
import com.questcape.integration.http.BoundedHttp;
import com.questcape.persistence.JsonStore;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.*;

import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class GuideRepositoryTest
{
	private JsonStore store;
	private BoundedHttp http;
	private GuideRepository repo;

	@Before
	public void setup() throws Exception
	{
		store = com.questcape.persistence.TestStores.store(new Gson(), Files.createTempDirectory("oqg-guide-test"));
		http = mock(BoundedHttp.class);
		repo = new GuideRepository(new GuideParser(), http, store);
	}

	private String payload(String html)
	{
		JsonObject parse = new JsonObject(), body = new JsonObject(), text = new JsonObject();
		text.addProperty("*", html);
		parse.add("text", text);
		parse.addProperty("revid", 123);
		body.add("parse", parse);
		return body.toString();
	}

	private BoundedHttp.Result result(int code, String body)
	{
		return new BoundedHttp.Result(code, body, "tag", "modified", null, null);
	}

	@Test
	public void malformedCachedEnrichmentCannotAuthorizeOverwritingTheOriginal() throws Exception
	{
		GuideSnapshot cached = new GuideSnapshot("cached", 1000, 2000, null, null,
			new GuideParser().parse(GuideParserTest.fixture()));
		JsonStore retained = mock(JsonStore.class);
		when(retained.read("guide", "standard", GuideSnapshot.class)).thenReturn(cached);
		GuideParser parser = mock(GuideParser.class);
		when(parser.reclassify(any())).thenThrow(new IllegalArgumentException("Malformed optional enrichment"));
		when(parser.parse(anyString())).thenReturn(cached.getRows());
		GuideRepository guarded = new GuideRepository(parser, http, retained);
		try
		{
			guarded.load();
			fail("Malformed input must be retained");
		}
		catch (IOException expected)
		{
			assertTrue(expected.getMessage().contains("original retained"));
		}
		when(http.get(anyString(), anyMap(), anyInt())).thenReturn(result(200, payload(GuideParserTest.fixture())));
		assertNotNull(guarded.refresh(Runnable::run, 10000).join());
		assertEquals(com.questcape.persistence.StoredView.SaveState.UNSAVED, guarded.view().getSaveState());
		verify(retained, never()).write(anyString(), anyString(), any());
	}

