public class UnlockProgressTest
{
	private static GuideRow row(String title) throws Exception
	{
		return new GuideParser().parse(GuideParserTest.table(GuideParserTest.activity(title))).get(0);
	}

	private static AccountProgress account(Client client)
	{
		return new AccountProgress("live:test:STANDARD", "Synthetic", "STANDARD", "Live RuneLite", 1, 1L,
			Map.of("SHADES_OF_MORTTON", AccountProgress.QuestStatus.COMPLETE,
				"BONE_VOYAGE", AccountProgress.QuestStatus.COMPLETE), Map.of("HERBLORE", 99),
			ActivityProgress.readActivities(client), Set.of());
	}

	@Test
	public void balloonRoutesAreIndependentAndRequireTheirExactFlag() throws Exception
	{
		Client client = mock(Client.class);
		String[] destinations = {"Crafting Guild", "Varrock", "Castle Wars", "Grand Tree"};
		int[] flags = {VarbitID.ZEP_MULTI_CRAFT, VarbitID.ZEP_MULTI_VARR, VarbitID.ZEP_MULTI_CAST, VarbitID.ZEP_MULTI_GNO};
		Set<String> keys = new HashSet<>();
		for (int i = 0; i < flags.length; i++)
		{
			reset(client);
			GuideRow target = row("Unlock: Balloon transport system to " + destinations[i]);
			keys.add(target.getKey());
			assertFalse(target.isManual());
			for (int value : new int[] {0, 1, 2})
			{
				when(client.getVarbitValue(flags[i])).thenReturn(value);
				AccountProgress live = account(client);
				for (int j = 0; j < destinations.length; j++)
				{
					assertEquals(i == j && value == 1 ? Completion.State.COMPLETE : Completion.State.INCOMPLETE,
						Completion.of(row("Unlock: Balloon transport system to " + destinations[j]), live).getState());
				}
			}
		}
		assertEquals(4, keys.size());
	}

	@Test
	public void strongholdNeedsAllCoinRewardsWithoutRequiringBoots() throws Exception
	{
		Client client = mock(Client.class);
		GuideRow stronghold = row("Unlock: Stronghold of Security");
		when(client.getVarbitValue(VarbitID.SOS_EMOTE_STAMP)).thenReturn(1);
		assertEquals(Completion.State.INCOMPLETE, Completion.of(stronghold, account(client)).getState());
		when(client.getVarbitValue(VarbitID.SOS_EMOTE_STAMP)).thenReturn(0);
		when(client.getVarbitValue(VarbitID.SOS_EMOTE_FLAP)).thenReturn(1);
		when(client.getVarbitValue(VarbitID.SOS_EMOTE_DOH)).thenReturn(1);
		assertEquals(Completion.State.INCOMPLETE, Completion.of(stronghold, account(client)).getState());
		when(client.getVarbitValue(VarbitID.SOS_EMOTE_IDEA)).thenReturn(1);
		assertEquals(Completion.State.COMPLETE, Completion.of(stronghold, account(client)).getState());
	}

	@Test
	public void campAndHandInRequireRewardsRatherThanPrerequisitesOrLevels() throws Exception
	{
		Client client = mock(Client.class);
		GuideRow camp = row("Unlock: Museum Camp");
		GuideRow handIn = row("Hand in the diary of Herbi Flax to the Apothecary. This trains Herblore.");
		when(client.getVarbitValue(VarbitID.FOSSIL_CAMP)).thenReturn(1);
		when(client.getVarbitValue(VarbitID.FOSSIL_BANK)).thenReturn(1);
		when(client.getVarbitValue(VarbitID.FOSSIL_TASKREWARDS_NORTH)).thenReturn(1);
		when(client.getVarpValue(VarPlayerID.MORTTONMULTI)).thenReturn(Integer.MIN_VALUE | (1 << 29));
		assertEquals(Completion.State.INCOMPLETE, Completion.of(camp, account(client)).getState());
		assertEquals(Completion.State.INCOMPLETE, Completion.of(handIn, account(client)).getState());
		when(client.getVarbitValue(VarbitID.FOSSIL_TASKREWARDS_CAMP)).thenReturn(1);
		when(client.getVarpValue(VarPlayerID.MORTTONMULTI)).thenReturn(Integer.MIN_VALUE | (1 << 30));
		assertEquals(Completion.State.COMPLETE, Completion.of(camp, account(client)).getState());
		assertEquals(Completion.State.COMPLETE, Completion.of(handIn, account(client)).getState());
		assertFalse(handIn.isManual());
		assertEquals(GuideRow.Kind.ACTIVITY, handIn.getKind());
	}

	@Test
	public void allNonKudosChecksAreInertAndStaleCallbacksCannotWriteThem() throws Exception
	{
		Client client = mock(Client.class);
		JsonStore store = mock(JsonStore.class);
		ProgressService service = new ProgressService(store);
		List<GuideRow> rows = new GuideParser().parse(GuideParserTest.fixture());
		Set<String> oldKeys = new HashSet<>();
		rows.forEach(r -> oldKeys.add(r.getKey()));
		AccountProgress old = account(client).withManual(oldKeys);
		when(store.read("progress", old.getScope(), AccountProgress.class)).thenReturn(old);
		service.acceptLive(account(client));
		clearInvocations(store);
		int manual = 0, automatic = 0;
		for (GuideRow row : rows)
		{
			if (row.isManual())
			{
				manual++;
				assertTrue(row.getTitle().endsWith("Kudos"));
				assertEquals(Completion.State.COMPLETE, Completion.of(row, service.current()).getState());
			}
			else
			{
				service.toggleManual(old.getScope(), row, true);
				if (row.getActivityIdentity() != null && row.getKind() != GuideRow.Kind.DIARY)
				{
					automatic++;
					assertEquals(row.getTitle(), Completion.State.INCOMPLETE, Completion.of(row, service.current()).getState());
				}
			}
		}
		assertEquals(2, manual);
		assertEquals(7, automatic);
		verifyNoInteractions(store);
		GuideRow future = row("Unlock: Uncharted balloon route");
		assertFalse(future.isManual());
		assertEquals(Completion.State.UNKNOWN, Completion.of(future, service.current()).getState());
		assertNull(ActivityProgress.handIn("Hand in a new item from Herbi Flax to someone else"));
	}
}

package com.questcape.progress.evaluation;

import com.questcape.guide.interpretation.TrainingInstruction;
import com.questcape.guide.model.GuideRow;
import com.questcape.guide.model.GuideSnapshot;
import com.questcape.guide.parsing.GuideParser;
import com.questcape.guide.parsing.GuideParserTest;
import com.questcape.progress.tracking.ProgressTest;
import java.util.*;
import org.junit.Test;

import static org.junit.Assert.*;

public class TrainingEvaluationTest
{
	@Test
	public void explainedPrayerAndFarmingMilestonesRemainTrainingInFreshAndLegacyRows() throws Exception
	{
		List<GuideRow> rows = new GuideParser().parse(GuideParserTest.fixture());
		List<GuideRow> reported = new ArrayList<>();
		for (GuideRow row : rows)
		{
			if (row.getTitle().startsWith("Train Prayer") && row.getTitle().contains("for Protect from")
				|| row.getTitle().startsWith("Train Farming") && row.getTitle().contains("letting crops grow"))
			{
				reported.add(row);
			}
		}
		assertEquals(4, reported.size());
		for (GuideRow row : reported)
		{
			GuideRow legacy = new GuideParser().reclassify(new GuideSnapshot("fixture", 1, 1, null, null,
				List.of(new GuideRow(row.getKey(), 0, row.getKind(), row.getTitle(), row.getWikiTarget(), null,
					row.getTargets(), row.getFields(), row.getLinks()))))
				.getRows().get(0);
			for (GuideRow candidate : List.of(row, legacy))
			{
				assertFalse(candidate.training().isUnresolved());
				assertEquals(1, candidate.training().getTargets().size());
				TrainingEvaluation actual = TrainingEvaluation.of(candidate,
					ProgressTest.observation("synthetic", "Fixture", "STANDARD", Map.of(),
						Map.of("PRAYER", 50, "FARMING", 50)));
				assertEquals(candidate.getTitle(), Completion.State.COMPLETE, actual.getState());
				assertEquals(Integer.valueOf(100), actual.getComparisons().get(0).getPercent());
			}
		}
		String farming = reported.stream().filter(row -> row.getTitle().startsWith("Train Farming")).findFirst()
			.orElseThrow().getTitle();
		int[] levels =
		{ 40, 41, 44, 46, 50 }, percentages =
		{ 0, 0, 60, 100, 100 };
		for (int i = 0; i < levels.length; i++)
		{
			TrainingEvaluation result = evaluate(farming, Map.of("FARMING", levels[i]));
			assertEquals(levels[i] < 41 ? Completion.State.INCOMPLETE
				: levels[i] < 46 ? Completion.State.IN_PROGRESS : Completion.State.COMPLETE, result.getState());
			assertEquals(Integer.valueOf(percentages[i]), result.getComparisons().get(0).getPercent());
		}
		assertEquals(Completion.State.UNKNOWN,
			evaluate("Train Prayer from level 33 to level 37 for Protect from Magic and hand in a diary",
				Map.of("PRAYER", 50)).getState());
	}

	private static GuideRow row(String title) throws Exception
	{
		return new GuideParser().parse(GuideParserTest.table(GuideParserTest.activity(title))).get(0);
	}

	private static TrainingEvaluation evaluate(String title, Map<String, Integer> levels) throws Exception
	{
		return TrainingEvaluation.of(row(title),
			ProgressTest.observation("synthetic", "Fixture", "STANDARD", Map.of(), levels));
	}

	@Test
	public void explicitIntervalsUseRealLevelsAndFlooredClampedPercentages() throws Exception
	{
		for (int level : List.of(51, 52, 54, 55, 70))
		{
			TrainingEvaluation result = evaluate("Train Woodcutting from level 52 to level 55",
				Map.of("WOODCUTTING", level));
			assertEquals(level < 52 ? Completion.State.INCOMPLETE
				: level < 55 ? Completion.State.IN_PROGRESS : Completion.State.COMPLETE, result.getState());
			assertEquals(Integer.valueOf(level < 52 ? 0 : level == 52 ? 0 : level == 54 ? 66 : 100),
				result.getComparisons().get(0).getPercent());
			assertEquals(Integer.valueOf(level), result.getComparisons().get(0).getLevel());
		}
		assertEquals(Integer.valueOf(100), evaluate("Train Defence from level 60 to level 65", Map.of("DEFENCE", 65))
			.getComparisons().get(0).getPercent());
	}

	@Test
	public void targetOnlyAndDegenerateIntervalsNeverInventABase() throws Exception
	{
		for (String source : List.of("Train Mining to level 60", "Train Mining from level 60 to level 60",
			"Train Mining from level 70 to level 60"))
		{
			TrainingEvaluation result = evaluate(source, Map.of("MINING", 59));
			assertEquals(Completion.State.INCOMPLETE, result.getState());
			assertNull(result.getComparisons().get(0).getPercent());
			assertEquals(Completion.State.COMPLETE, evaluate(source, Map.of("MINING", 60)).getState());
		}
	}

	@Test
	public void missingOrInvalidLevelsAreNotZeroAndGoalsRemainDistinctFromAdvice() throws Exception
	{
		for (Map<String, Integer> levels : List.of(Map.<String, Integer>of(), Map.of("MINING", 0),
			Map.of("MINING", -1)))
		{
			TrainingEvaluation result = evaluate("Train Mining from level 55 to level 60", levels);
			assertEquals(Completion.State.UNKNOWN, result.getState());
			assertNull(result.getComparisons().get(0).getLevel());
			assertNull(result.getComparisons().get(0).getPercent());
		}
		GuideRow goal = row("Train Mining to level 60 (Recommended: train Strength from level 10 to level 40)");
		assertEquals(Map.of("MINING", 60), goal.getTargets());
		assertEquals(1, goal.training().getTargets().size());
		assertNull(goal.training().getTargets().get(0).getBase());
		GuideRow handIn = row("Hand in Herbi Flax diary, from level 25 to level 25");
		assertEquals(GuideRow.Kind.ACTIVITY, handIn.getKind());
		assertEquals(Completion.State.UNKNOWN,
			Completion
				.of(handIn,
					ProgressTest.observation("fixture", "Fixture", "STANDARD", Map.of(), Map.of("HERBLORE", 99)))
				.getState());
	}

	@Test
	public void compoundPrecedenceRetainsUsefulFactsWithoutFalseCompletion() throws Exception
	{
		String source = "Train Attack and Strength from level 10 to level 20";
		assertEquals(Completion.State.COMPLETE, evaluate(source, Map.of("ATTACK", 20, "STRENGTH", 20)).getState());
		assertEquals(Completion.State.IN_PROGRESS, evaluate(source, Map.of("ATTACK", 20, "STRENGTH", 9)).getState());
		assertEquals(Completion.State.IN_PROGRESS, evaluate(source, Map.of("ATTACK", 15)).getState());
		assertEquals(Completion.State.UNKNOWN, evaluate(source, Map.of("ATTACK", 20)).getState());
		assertEquals(Completion.State.INCOMPLETE, evaluate(source, Map.of("ATTACK", 9)).getState());
		assertEquals(Completion.State.UNKNOWN, evaluate(source, Map.of()).getState());
		TrainingEvaluation unknown = evaluate("Train Attack and Unrecognized from level 10 to level 20",
			Map.of("ATTACK", 20));
		assertTrue(unknown.isPartial());
		assertEquals(Completion.State.UNKNOWN, unknown.getState());
		assertEquals("ATTACK", unknown.getComparisons().get(0).getSkill());
	}

	@Test
	public void contradictoryOrUnsupportedTargetsDoNotComplete() throws Exception
	{
		for (String source : List.of("Train Attack to level 20 and Attack to level 30", "Train Mining to level 100",
			"Train Mystery to level 20"))
		{
			assertEquals(Completion.State.UNKNOWN, evaluate(source, Map.of("ATTACK", 99, "MINING", 99)).getState());
		}
		TrainingInstruction aliases = row("Train Defense and Runecrafting from level 10 to level 20").training();
		assertEquals(List.of("DEFENCE", "RUNECRAFT"),
			List.of(aliases.getTargets().get(0).getSkill(), aliases.getTargets().get(1).getSkill()));
	}

	@Test
	public void unsupportedRequirementsRemainNamedAndExtraActionsPreventFalseCompletion() throws Exception
	{
		TrainingEvaluation result = evaluate("Train Attack and Mystery from level 10 to level 20",
			Map.of("ATTACK", 20, "Mystery", 99));
		assertEquals(2, result.getComparisons().size());
		assertEquals("Mystery", result.getComparisons().get(1).getSkill());
		assertNull(result.getComparisons().get(1).getLevel());
		assertEquals(Completion.State.UNKNOWN, result.getState());
		assertEquals(Completion.State.UNKNOWN,
			evaluate("Train Mining from level 55 to level 60 and hand in a diary", Map.of("MINING", 60)).getState());
	}
}

package com.questcape.progress.tracking;

import com.questcape.guide.model.GuideRow;
import com.questcape.guide.parsing.GuideParser;
import com.questcape.guide.parsing.GuideParserTest;
import com.questcape.persistence.*;
import com.questcape.persistence.JsonStore;
import com.questcape.persistence.StoredView;
import com.questcape.progress.model.AccountProgress;
import java.io.IOException;
import java.util.*;
import java.util.concurrent.*;
import org.junit.Test;

import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class ManualIntentRecoveryTest
{
	private static GuideRow kudos(String title) throws Exception
	{
		return new GuideParser().parse(GuideParserTest.table(GuideParserTest.activity(title))).get(0);
	}

	@Test
	public void recoveredSavedCheckCannotResurrectClearedIntentAndUnrelatedChecksSurvive() throws Exception
	{
		JsonStore store = mock(JsonStore.class);
		ProgressService service = new ProgressService(store);
		GuideRow first = kudos("Unlock: Varrock Museum Kudos"), other = kudos("Unlock: More Varrock Museum Kudos");
		AccountProgress observation = ProgressTest.observation("fixture:A", "Fixture", "STANDARD", Map.of(), Map.of());
		AccountProgress saved = observation.withManual(Set.of(first.getKey(), other.getKey(), "retired:unknown"));
		when(store.read(eq("progress"), eq(observation.getScope()), eq(AccountProgress.class)))
			.thenThrow(new IOException("unreadable")).thenReturn(saved);
		service.acceptLive(observation);
		service.toggleManual(observation.getScope(), first, false);
		service.acceptLive(observation, service.token(), true);
		assertFalse(service.current().getManual().contains(first.getKey()));
		assertTrue(service.current().getManual().containsAll(Set.of(other.getKey(), "retired:unknown")));
		assertEquals(StoredView.SaveState.SAVED, service.view().getSaveState());
	}

	@Test
	public void blockedOldReadCannotReplaceNewSessionsSavedManualIntent() throws Exception
	{
		JsonStore store = mock(JsonStore.class);
		ProgressService service = new ProgressService(store);
		GuideRow row = kudos("Unlock: Varrock Museum Kudos");
		AccountProgress account = ProgressTest.observation("fixture:A", "Fixture", "STANDARD", Map.of(), Map.of());
		CompletableFuture<Void> entered = new CompletableFuture<>(), release = new CompletableFuture<>();
		java.util.concurrent.atomic.AtomicInteger reads = new java.util.concurrent.atomic.AtomicInteger();
		when(store.read("progress", account.getScope(), AccountProgress.class)).thenAnswer(call ->
		{
			if (reads.getAndIncrement() == 0)
			{
				entered.complete(null);
				release.get(5, TimeUnit.SECONDS);
				return account.withManual(Set.of(row.getKey()));
			}
			return null;
		});
		ExecutorService worker = Executors.newSingleThreadExecutor();
		long oldSession = service.token();
		try
		{
			Future<Boolean> old = worker.submit(() -> service.acceptLive(account, oldSession, false));
			entered.get(5, TimeUnit.SECONDS);
			service.logout();
			service.acceptLive(account, service.token(), true);
			service.toggleManual(account.getScope(), row, false);
			release.complete(null);
			assertFalse(old.get(5, TimeUnit.SECONDS));
			service.acceptLive(account, service.token(), true);
			assertFalse(service.current().getManual().contains(row.getKey()));
			assertEquals(StoredView.SaveState.SAVED, service.view().getSaveState());
		}
		finally
		{
			release.complete(null);
			worker.shutdownNow();
		}
	}

	@Test
	public void retainedManualActionCannotAdoptANewSessionForTheSameAccount() throws Exception
	{
		ProgressService service = new ProgressService(mock(JsonStore.class));
		GuideRow row = kudos("Unlock: Varrock Museum Kudos");
		AccountProgress account = ProgressTest.observation("fixture:A", "Fixture", "STANDARD", Map.of(), Map.of());
		service.acceptLive(account);
		long old = service.token();
		service.logout();
		service.acceptLive(account);
		service.toggleManual(account.getScope(), row, true, old);
		assertFalse(service.current().getManual().contains(row.getKey()));
		service.toggleManual(account.getScope(), row, true, service.token());
		assertTrue(service.current().getManual().contains(row.getKey()));
	}

	@Test
	public void successfulOldSaveCannotAcknowledgeANewerFailedEdit() throws Exception
	{
		JsonStore store = mock(JsonStore.class);
		ProgressService service = new ProgressService(store);
		GuideRow row = kudos("Unlock: Varrock Museum Kudos");
		AccountProgress account = ProgressTest.observation("fixture:A", "Fixture", "STANDARD", Map.of(), Map.of());
		service.acceptLive(account);
		CompletableFuture<Void> entered = new CompletableFuture<>(), release = new CompletableFuture<>();
		java.util.concurrent.atomic.AtomicInteger writes = new java.util.concurrent.atomic.AtomicInteger();
		doAnswer(call ->
		{
			if (writes.getAndIncrement() == 0)
			{
				entered.complete(null);
				release.get(5, TimeUnit.SECONDS);
			}
			else
			{
				throw new IOException("later edit unsaved");
			}
			return null;
		}).when(store).write(anyString(), anyString(), any());
		ExecutorService worker = Executors.newSingleThreadExecutor();
		try
		{
			Future<?> old = worker.submit(() ->
			{
				try
				{
					service.toggleManual(account.getScope(), row, true);
				}
				catch (IOException e)
				{
					throw new CompletionException(e);
				}
			});
			entered.get(5, TimeUnit.SECONDS);
			service.toggleManual(account.getScope(), row, false);
			release.complete(null);
			old.get(5, TimeUnit.SECONDS);
			assertFalse(service.current().getManual().contains(row.getKey()));
			assertEquals(StoredView.SaveState.UNSAVED, service.view().getSaveState());
		}
		finally
		{
			release.complete(null);
			worker.shutdownNow();
		}
	}
}

