				panel.resetButton().doClick();
				assertEquals("", panel.searchField().getText());
				assertEquals(5, panel.visibleRowCount());
				assertFalse(panel.searchPending());
			});
		}
		finally
		{
			SwingUtilities.invokeAndWait(observer::stop);
		}
	}

